(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,79794,(A,P,I)=>{P.exports=JSON.parse('[{"주제":"GPUBASE 연동","개요":"GPUBASE 계정으로 AGENTBASE 에 들어오는 조건, 구분 결정, 역할과 권한 변경의 반영 시점, 그룹 탈퇴와 워크로드 종료 때의 처리를 다룬다.","묶음":[{"제목":"진입 대상과 계정","문장":["사용자가 GPUBASE 워크로드에서 AGENTBASE 를 열면 시스템이 GPUBASE 계정과 역할을 읽어 구분을 정하고 홈으로 들인다.","AGENTBASE 는 별도 가입과 로그인을 두지 않는다.","들어올 수 있는 계정은 그 워크로드가 속한 그룹의 구성원 가운데 워크로드 생성자와 공개 설정 대상이다.","워크로드 전체 공개는 쓰지 않는다. 로그인 없이는 구분을 정할 수 없기 때문이다.","다만 라이선스 구성원 한도에 닿으면 새 구성원의 진입을 막고 「라이선스 구성원 한도에 닿아 들어갈 수 없습니다.」를 보인다.","한도에 닿아도 이미 들어온 구성원은 계속 쓴다."]},{"제목":"구분 결정","문장":["구분은 관리자와 AI 개발자 둘이다.","GPUBASE 그룹 관리자 이상은 AGENTBASE 관리자로 고정되고, 시스템 설정에서 구분을 바꿀 수 없다.","진입 자체가 그 그룹의 워크로드이므로 그룹 관리자에게 범위 조건은 따로 두지 않는다.","워크로드 생성자는 워크로드를 만들 때 자신을 관리자로 둘지 AI 개발자로 둘지 고른다.","생성자가 관리자로 들어와도 다른 관리자는 그 생성자를 AI 개발자로 내릴 수 있다.","그 밖의 구성원은 AI 개발자로 들어오고, 관리자가 시스템 설정의 구성원 권한에서 관리자로 지정한다.","그룹 관리자는 대시보드에서 시스템 관리자와 같은 전체 범위를 본다."]},{"제목":"역할과 권한 변경의 반영 시점","문장":["GPUBASE 역할은 구성원이 다음에 AGENTBASE 에 들어올 때 다시 읽는다.","다시 읽은 역할이 그룹 관리자 이상이면 그 구성원은 관리자로 고정된다.","그룹 관리자 아래로 내려가면 AGENTBASE 에서 지정한 구분으로 돌아가고, 지정한 구분이 없으면 AI 개발자가 된다.","진입 때 바뀐 구분은 감사 이력에 남는다.","AGENTBASE 권한은 관리자가 스위치를 바꾸는 순간 적용되고, 그 구성원의 버튼이 [{동작}]과 [{동작} 요청] 사이에서 즉시 바뀐다.","권한이 생기면 그 권한으로 보낸 승인 대기 요청은 그 순간 자동 취소된다.","다만 마지막 관리자는 AI 개발자로 바꿀 수 없고, 관리자 수에는 그룹 관리자 이상도 넣는다."]},{"제목":"GPUBASE 역할 제한 적용","문장":["AGENTBASE 에서 실행한 학습과 배포에는 그 일을 실행한 구성원의 GPUBASE 역할 제한이 걸린다.","GPUBASE 역할 제한이 바뀌면 그다음 학습 실행과 배포부터 바뀐 제한을 적용한다.","다만 이미 시작한 학습과 배포는 시작할 때의 제한으로 끝까지 진행한다."]},{"제목":"자원 한도 변경 요청의 처리 주체","문장":["AGENTBASE 에서 보낸 자원 한도 변경 요청은 GPUBASE 가 받아 승인하거나 거절한다.","AGENTBASE 는 요청을 GPUBASE 에 보내고, 처리 결과를 받아 요청자에게 알림으로 전한다.","GPUBASE 가 승인하는 순간 워크로드 할당량이 바뀐다.","요청을 받고 승인하는 기능은 GPUBASE 에 둔다.","다만 GPUBASE 에 요청을 보내지 못하면 요청을 만들지 않고 「GPUBASE에 요청을 보내지 못했습니다.」를 보인다."]},{"제목":"진입 준비 확인","문장":["AGENTBASE 에 들어올 때마다 시스템은 GPU 노드 풀 할당, CPU·RAM 할당, 스토리지 할당, 오케스트레이터 연결 넷을 확인한다.","준비되지 않은 항목이 있어도 진입은 막지 않고, 진입할 때 준비되지 않은 항목과 이유를 안내한다.","준비되지 않은 동안 조회는 모두 허용하고, 그 항목이 필요한 실행 버튼만 비활성으로 두고 이유를 보인다.","GPU 노드 풀 할당이 없으면 GPU 를 쓰는 학습과 모델 배포를 막고 「GPU 노드 풀이 할당되지 않아 실행할 수 없습니다.」를 보인다.","CPU·RAM 할당이 없으면 자원을 점유하는 모든 실행과 배포를 막는다.","스토리지 할당이 없으면 업로드와 산출물을 남기는 생성·실행을 막는다.","오케스트레이터가 연결되지 않으면 홈은 작업 전환 위젯 배치를 쓴다.","준비가 끝나면 다음 상태 갱신 때(상단바 갱신 주기, 처음 값 15초) 막힌 버튼이 풀린다."]},{"제목":"그룹 탈퇴","문장":["구성원이 GPUBASE 그룹에서 빠져도 그 사람이 만든 작업은 남고 생성자 이름도 바꾸지 않는다.","그 사람의 승인 대기 요청은 시스템이 자동 취소하고, 감사 이력에 결과 「요청 취소」, 처리자 「시스템」으로 남긴다.","그 사람이 쥐고 있던 편집 점유는 즉시 놓인다.","그 사람이 걸어 둔 자원 대기 작업은 대기를 끝내고 중지로 바뀐다.","다만 그 사람이 시작해 실행 중인 학습과 배포는 멈추지 않는다.","이후 그 작업의 조작은 남은 구성원이 권한 규칙대로 한다.","요청자가 그룹을 떠나도 감사 이력 기록은 지우지 않는다."]},{"제목":"워크로드 종료","문장":["GPUBASE 에서 워크로드를 종료하면 사용자 화면의 접속만 끝나고 점유한 자원은 그대로 유지된다.","실행 중인 모델 배포, 에이전트, 서비스 API 는 내리지 않으므로 서비스 호출이 끊기지 않는다.","진행 중인 학습, 데이터 파이프라인 전체 실행, 검색 DB 업데이트는 끝까지 실행하고 끝나면 자원을 반환한다.","자원 대기 작업과 예약 작업도 그대로 남는다."]}]},{"주제":"프로젝트 공통","개요":"모든 작업 메뉴가 함께 따르는 상태 이름, 저장 조건, 배포 중 삭제 차단, 삭제된 참조 처리, 커밋 삭제 기준을 다룬다.","묶음":[{"제목":"미배포 상태 이름","문장":["만든 뒤 한 번도 배포하지 않은 작업의 상태는 「생성됨」이다.","에이전트도 한 번도 배포하지 않았으면 「생성됨」이고, 상태 표시, 상태 거르기, 복제 결과가 모두 같은 이름을 쓴다.","복제한 작업은 자원 없이 「생성됨」 상태로 만들어진다.","에이전트의 상태는 생성됨, 설치중, 배포중, 중지, 실패 다섯이고 대기와 실행중은 없다.","지식베이스와 데이터 파이프라인의 상태는 생성됨, 대기, 설치중, 배포중, 실행중, 중지, 실패 일곱이다.","모델 배포와 도구·MCP 의 상태는 생성됨, 대기, 설치중, 배포중, 중지, 실패 여섯이다.","파운데이션 모델의 상태는 생성됨, 대기, 설치중, 실행중, 종료, 중지, 실패 일곱이고 배포중은 없다."]},{"제목":"저장 조건","문장":["사용자가 [생성]이나 [저장]을 누르면 시스템은 필수값, 형식, 이름 중복, 변경 여부, 외부 접속을 검사한다.","다섯 검사를 모두 통과해야 저장하고, 하나라도 걸리면 저장하지 않는다.","이름은 필수이고, 같은 메뉴 안에 같은 이름이 있으면 저장을 막는다.","에이전트 이름은 100자까지이고 「/」를 쓸 수 없으며, 대소문자만 다른 이름도 같은 이름으로 본다.","수정 창에서 바꾼 값이 없으면 저장을 막고 「변경한 항목이 없습니다.」를 보인다.","외부 주소와 키를 받는 칸은 저장하는 순간 접속을 확인하고, 실패하면 저장하지 않고 칸 아래에 이유를 보인다.","접속을 확인하는 칸은 외부 엔드포인트, 상용 API, 서비스 연결, 사용자·권한 API 연결이다.","검사에 여러 개가 걸리면 먼저 걸린 이유 하나만 보인다.","저장에 실패해도 입력한 값은 지우지 않고 이유만 보인다."]},{"제목":"배포 중 삭제 차단","문장":["대기, 설치중, 배포중, 실행중인 모델 배포, 에이전트, 지식베이스, 도구, 데이터 파이프라인은 삭제할 수 없다.","이때 [삭제]는 비활성이고 「배포 중인 {작업}은 삭제할 수 없습니다. [배포 중지] 뒤 삭제합니다.」를 보인다.","사용자가 [배포 중지]로 자원을 반환해 중지가 되면 그 순간부터 삭제할 수 있다.","실패 상태는 자원을 반환한 상태라 바로 삭제할 수 있다.","파운데이션 모델은 대기 중이면 [실행 취소] 뒤, 실행중이면 [중지] 뒤 삭제한다.","배포중인 에이전트가 부르거나 검색 DB가 준비된 지식베이스가 쓰는 모델 배포는 삭제할 수 없다.","실행 중인 데이터 파이프라인이 쓰는 모델 배포도 삭제할 수 없다.","다만 승인 대기 중인 요청이 있는 작업은 상태와 관계없이 삭제를 막는다.","다른 구성원이 편집 중인 작업도 삭제를 막고 「{이름}님이 편집 중입니다.」를 보인다.","목록의 [삭제]는 상세의 [삭제]와 같은 조건, 같은 문구로 막는다."]},{"제목":"삭제된 참조 처리","문장":["에이전트가 쓰던 모델 배포, 지식베이스, 도구, 호출 대상 에이전트가 삭제되어도 참조를 자동으로 지우지 않는다.","지운 대상은 그 노드에 「삭제됨」으로 남는다.","「삭제됨」 참조가 있는 에이전트는 편집자가 참조를 해제하거나 다른 대상을 고르기 전까지 배포할 수 없다.","시스템은 에이전트 상세에 들어올 때와 [배포]를 누를 때 연결 대상의 상태를 다시 확인한다.","도구 동작이 사용 안 함이 되면 노드에 「{동작} 사용 안 함」으로 남는다.","다만 배포중인 에이전트가 부르는 모델 배포는 삭제 자체를 막으므로, 운영 중인 에이전트의 모델 참조는 「삭제됨」이 되지 않는다.","배포중인 에이전트의 연결 대상이 내려가면 에이전트는 배포중으로 남고, 그 노드를 지나는 요청은 실패한다."]},{"제목":"커밋과 파운데이션 모델 삭제 기준","문장":["어떤 모델 배포가 커밋을 쓰고 있으면 그 모델 배포의 상태와 관계없이 커밋을 삭제할 수 없다.","그 커밋이 든 파운데이션 모델도 같은 이유로 삭제할 수 없다.","막히면 「{모델 배포} 모델 배포가 커밋 {커밋}을 사용하고 있어 삭제할 수 없습니다.」를 보인다.","사용자는 모델 배포에서 다른 커밋으로 바꾸거나 모델 배포를 삭제한 뒤 커밋을 삭제한다.","대기나 실행 중인 학습이 이어서 학습하는 커밋은 그 학습이 끝나거나 중지될 때까지 삭제할 수 없다.","기본 커밋은 수정, 삭제, 다운로드할 수 없다.","여러 커밋을 골라 지울 때 모델 배포가 쓰는 커밋이 하나라도 섞이면 [삭제]를 막는다.","파운데이션 모델을 삭제하면 그 작업의 체크포인트와 커밋을 함께 지운다."]}]},{"주제":"데이터 관리","개요":"원본 데이터와 데이터셋 파일의 업로드, 같은 이름 처리, 회차 저장과 지난 회차 보관, 연결 작업 보호, 편집 점유, 다운로드 승인, 스토리지 한도를 다룬다.","묶음":[{"제목":"업로드 진행과 실패","문장":["사용자가 파일 업로드를 시작하면 다른 화면으로 옮겨도 업로드는 계속된다.","진행 상황은 상단바 데이터 업로드 현황에 파일별로 보이고, 완료 건수, 업로드 중 건수, 진행률, 남은 시간을 적는다.","파일 줄의 [중지]나 [전체 중지]는 확인 창을 거쳐 그 파일을 「중지됨」으로 끝내고, 이미 끝난 파일은 그대로 둔다.","AGENTBASE 에서 나갈 때 진행 중인 업로드가 있으면 확인 창을 열고, 나가면 끝나지 않은 파일은 「중지됨」이 된다.","다만 네트워크가 끊기거나 브라우저를 닫거나 스토리지 사용률이 95% 에 닿으면 올리던 파일은 저장하지 않고 실패로 끝낸다.","실패가 나면 사용자가 어느 화면에 있든 「업로드 실패」 창을 열고 「n건을 업로드했고 n건은 실패했습니다.」를 보인다.","실패한 파일은 이어 올리지 않고, 사용자가 다시 골라 처음부터 올린다.","선택한 파일 합이 잔여 스토리지보다 크면 업로드를 시작하지 않는다.","원본 데이터는 모든 파일과 폴더를 받고, 데이터셋은 Parquet, CSV, JSONL 파일만 받는다.","데이터셋으로 올린 CSV와 JSONL은 Parquet으로 바꿔 저장한다.","처음 올린 파일은 0회차다.","작업이 생성한 데이터 폴더에는 올릴 수 없다.","외부 주소에서 바로 가져오는 업로드는 없고, 외부 데이터는 데이터 파이프라인 수집 노드가 가져온다."]},{"제목":"같은 이름 파일 처리","문장":["올릴 파일과 같은 이름이 저장 위치에 있으면 중복 파일 확인 창에서 파일마다 처리 방식을 고른다.","처리 방식은 새 이름으로 저장, 덮어쓰기, 건너뛰기 셋이고 처음 값은 새 이름으로 저장이다.","건너뛴 파일은 용량 계산에서 뺀다.","덮어쓰면 기존 파일의 새 회차로 저장한다.","연결 작업이 있는 파일도 덮어쓸 수 있고, 저장 전에 「새 회차로 저장」 확인 창을 거친다.","다만 다른 구성원이 그 파일을 편집 중이면 [덮어쓰기]만 비활성이고 「{이름}님이 편집 중이라 덮어쓸 수 없습니다.」를 보인다.","두 구성원이 같은 이름을 거의 동시에 올리면 먼저 저장을 마친 파일이 그 이름을 갖는다.","나중에 끝난 쪽은 저장 직전에 이름을 다시 확인해 새 이름으로 저장하므로, 사람이 고르지 않은 덮어쓰기는 일어나지 않는다."]},{"제목":"회차 저장과 연결 작업 반영","문장":["원본 데이터의 회차는 미리보기 편집 저장, 파일 교체, 같은 이름 덮어쓰기로 파일 내용이 바뀔 때만 오른다.","이름 변경, 이동, 복사, 다운로드는 회차를 올리지 않고 지금 회차의 작업 이력에 한 줄로 남는다.","연결 작업이 있는 파일을 저장하면 저장 전에 「새 회차로 저장」 확인 창이 연결 작업 수, 반영 방식, 연결 작업 이름 전부를 보인다.","연결 작업은 파운데이션 모델의 학습·테스트 데이터셋, 지식베이스, 데이터 파이프라인 소스, 모델 배포의 저장한 벤치마크 결과다.","지식베이스는 새 회차로 자동으로 바뀌지만 [검색 DB 업데이트]가 끝나기 전까지 「반영 대기」이고 이전 회차로 검색한다.","파인 튜닝은 지금 회차를 고정해 두고, 다음 실행 때 사람이 새 회차를 고른다.","데이터 파이프라인은 전체 실행을 시작할 때마다 그 시점의 최신 회차를 읽는다.","저장 뒤 그 파일을 쓰는 작업마다 생성자와 관리자 전원에게 「데이터 새 회차」 알림을 한 건 보내고, 파일 작업 이력에 한 줄을 남긴다.","다만 연결 작업이 없는 파일의 편집과 교체는 알림을 만들지 않는다.","편집할 수 있는 형식은 CSV, TSV, XLSX, XLS, DOCX, DOC, TXT, MD, JSON, JSONL 이다.","발행된 데이터셋 버전을 고쳐 저장하면 새 버전 vN+1 로 저장하고 원래 버전은 그대로 남긴다."]},{"제목":"지난 회차 보관과 삭제","문장":["지난 회차의 파일 실물은 그 회차를 쓰는 연결 작업이 있는 동안만 보관한다.","마지막으로 쓰던 작업이 새 회차로 바뀌는 순간 시스템이 그 지난 회차 실물을 지운다.","지식베이스가 쓰던 회차는 그 지식베이스의 [검색 DB 업데이트]가 끝나는 순간 지운다.","연결 작업이 없는 파일은 새 회차를 저장하는 순간 지난 회차 실물을 지운다.","보관하는 동안 지난 회차 용량은 스토리지 사용량에 들어가고, 파일 상세에 「보관 회차 n개, n GB」로 보인다.","지난 회차는 조회, 다운로드, 되돌리기를 제공하지 않고, 쓰는 작업의 재현에만 쓴다.","실물을 지워도 회차 기록은 작업 이력에 남는다."]},{"제목":"연결 작업이 있는 데이터 보호","문장":["연결 작업이 있는 데이터는 이름 변경, 이동, 삭제를 막고 「연결 작업이 있어 이름 변경, 이동, 삭제할 수 없습니다.」를 보인다.","내용 편집, 파일 교체, 업로드 덮어쓰기, 복사, 다운로드는 연결 작업이 있어도 허용한다.","연결 작업이 배포 전이든 중지든 같은 규칙으로 막고, 연결 작업이 지워지는 순간 막힘이 풀린다.","연결 작업이 있는 데이터와 없는 데이터를 함께 고르면 [삭제]는 비활성이고 [이동/복사]는 「복사」로 고정된다.","복사본은 연결 작업이 없는 새 데이터이고, 원본을 지우려면 연결 작업에서 원본을 해제해야 한다.","작업이 생성한 데이터(체크포인트, 모델, 지식베이스, 서비스 폴더)는 수정, 이동, 삭제, 복사, 다운로드를 모두 막는다.","다만 작업이 생성한 데이터 가운데 평가셋 파일은 하나씩 지울 수 있다.","파일을 삭제하면 파일과 그 작업 이력을 함께 지우고, 삭제 사실은 감사 이력에 남긴다."]},{"제목":"데이터 편집 점유","문장":["구성원이 데이터 한 개의 상세를 열거나 수정, 이동, 삭제를 시작하면 그 데이터를 점유한다.","점유 중에는 다른 구성원의 이름 변경, 편집, 이동, 삭제, 복사, 다운로드, 업로드 덮어쓰기, 체크 선택을 막는다.","점유는 창을 닫거나 접속이 끝나거나 3분 동안 조작이 없으면 풀리고, 2분 30초에 「30초 뒤 뷰어로 전환합니다.」를 보인다.","3분 무조작으로 풀리면 열린 창을 닫고 저장하지 않은 입력은 버린다.","점유자가 점유를 놓는 순간 다른 구성원의 막힌 조작이 풀린다."]},{"제목":"다운로드 승인","문장":["다운로드 권한이 있는 구성원과 관리자는 「다운로드」 확인 창 뒤 바로 받는다.","권한이 없으면 [다운로드 요청]을 보내고, 관리자가 승인하면 요청자가 같은 자리에서 1회 받는다.","승인은 1회 다운로드, 승인 후 7일 경과, 그 파일의 회차 변경 가운데 먼저 오는 때 끝난다.","끝난 승인은 감사 이력에 결과 「만료」와 끝난 이유로 남고, 다시 받으려면 새로 요청한다.","폴더나 여러 파일의 승인은 요청할 때의 파일 목록과 각 파일의 회차에 고정되고, 승인 뒤 더해진 파일은 들어가지 않는다.","다만 이동이나 복사로 같은 이름 파일을 덮어쓰면 원래 파일이 지워진 것으로 보아 그 파일의 승인도 사라진다.","승인을 기다리는 동안 그 데이터의 내 다운로드는 비활성이고, 다른 구성원의 다운로드는 막지 않는다.","다른 구성원이 그 파일을 편집 중이면 승인이 있어도 「{이름}님이 편집 중입니다.」로 막히고, 편집이 끝나는 순간 풀린다.","요청 뒤 다운로드 권한이 생기면 대기 요청은 자동 취소되고 요청자는 바로 받는다.","승인을 받은 뒤 권한을 회수당해도 받지 않은 승인은 끝날 조건까지 유효하다.","누가 받든 감사 이력에 「다운로드」 한 건, 파일 작업 이력에 한 줄을 남긴다.","작업이 생성한 데이터는 권한과 관계없이 받을 수 없다."]},{"제목":"스토리지 한도","문장":["스토리지 할당량은 GPUBASE 가 이 워크로드에 정한 값이고, 업로드 파일과 작업 산출물이 함께 쓴다.","사용률이 스토리지 알림 사용률(처음 값 80%)에 닿으면 구성원 전원에게 저장 용량 알림을 보낸다.","사용률이 95% 에 닿으면 구성원 전원에게 다시 알리고, 진행 중인 업로드를 실패로 끝낸다.","95% 이상인 동안 새 파운데이션 모델, 커밋, 검색 DB, 모델 배포 생성을 막는다.","95% 이상인 동안 학습 실행과 데이터 파이프라인 전체 실행의 시작도 막는다.","사람이 정리하거나 할당량이 늘어 사용률이 95% 아래로 내려가면 생성과 실행 차단이 풀린다.","복사는 복사할 크기로 잔여 스토리지를 검사하고, 이동은 검사하지 않는다.","다만 저장 용량 알림을 꺼도 95% 차단은 그대로 적용된다."]}]},{"주제":"데이터 파이프라인","개요":"배포로 점유한 실행 자원 안에서 표본 실행, 전체 실행, 실행 일정, 라벨링 대기와 검수, 중지와 이어서 실행, 발행과 데이터셋 버전 관리가 동작하는 방식을 다룬다.","묶음":[{"제목":"배포와 실행 자원","문장":["사용자가 [배포] 창에서 노드 풀, GPU, CPU, RAM 한 벌과 실행 시점을 정하면 설치중을 거쳐 배포중이 된다.","배포중이 된 순간 배포 회차가 열리고, [배포 중지]까지 그 자원을 점유한다.","모든 노드의 표본 실행과 전체 실행이 이 한 벌을 나눠 쓰고, 노드별 실행 자원은 없다.","GPU 를 0 EA 로 정하면 CPU 와 RAM 만 쓴다.","배포 중에는 실행 자원을 바꿀 수 없고, [배포 중지] 뒤 다시 [배포]하면 새 배포 회차가 열린다.","[배포]는 컴퓨팅 자원 사용 권한이 필요하고, 권한이 없으면 [배포 요청]을 보내 승인되는 순간 요청한 값으로 배포한다.","생성, 전체 실행, 표본 실행, 실행 중지, 발행, 발행 취소, 설정 편집은 권한 없이 한다.","자원이 모자라거나 예약한 시점 전이면 대기 상태로 기다리고, 대기 중 자원 점유는 0이다.","[생성]하면 데이터 파이프라인과 같은 이름의 빈 출력 데이터셋을 함께 만든다."]},{"제목":"[실행 중지]와 [배포 중지]","문장":["[실행 중지]는 진행 중인 전체 실행만 멈추고 상태를 배포중으로 돌리며, 자원은 계속 점유한다.","[실행 중지] 확인 창에서 중간 산출물 보관 여부를 고르고, 처음 값은 보관이다.","보관하면 다음 전체 실행에서 시작 위치 「이어서」를 골라 멈춘 노드부터 처리한다.","멈춘 순간 돌던 노드는 대기로 돌리고, 작업 이력의 실행 줄 결과는 「중지」다.","보관한 중간 산출물은 다음 전체 실행(처음부터·이어서)이나 설정 변경 때 지우고, 보관하는 동안 스토리지 사용량에 든다.","[배포 중지]는 권한과 관계없이 확인 창 뒤 바로 자원을 반환하고, 상태를 중지로 바꾸며 그 배포 회차를 끝낸다.","다만 전체 실행 중(라벨링 대기 포함)에는 [배포 중지]가 막히고, 사용자는 [실행 중지]로 실행을 먼저 멈춘 뒤 중지한다.","표본 실행 중과 발행 중에도 [배포 중지]를 막는다.","[배포 중지] 뒤에도 설정, 실행 결과, 데이터셋 버전은 남는다.","대기나 예약 중의 [배포 중지]는 대기나 예약을 취소해 중지로 돌리고, 실행자와 관리자만 할 수 있다.","확인 창을 연 사이 자원이 잡혀 설치중이 되었어도, 확인하면 설치를 취소하고 중지로 처리한다."]},{"제목":"전체 실행과 실패","문장":["배포중인 파이프라인에서 [전체 실행]을 누르면 시작 위치(처음부터, 이어서)를 받아 바로 원본 전체를 출력 노드까지 처리한다.","실행하는 동안 상태는 실행중이고, 끝나면 배포중으로 돌아가며 실행 결과 하나가 파이프라인 안에 생긴다.","실행 결과는 하나만 두고, 발행하지 않은 지난 실행 결과는 새 실행 결과로 대체한다.","[전체 실행]을 막는 차례는 다른 구성원 편집 중, 배포중 아님, 발행 중, 스토리지 95% 이상, 원본 폴더 빔, 설정 미완성이다.","스토리지 사용률이 95% 이상이면 시작을 막고 「스토리지 사용률이 95% 이상이라 실행할 수 없습니다.」를 보인다.","고른 모델 배포가 운영 중이 아니면 「{모델 배포} 운영 중 아님」으로 전체 실행을 막는다.","실행이 도중에 실패하면 상태는 배포중으로 돌아가고 배포 회차와 자원은 그대로 이어진다.","실패하면 작업 이력의 실행 줄에 결과 「실패」와 실행 시간이 남고, 실행자와 관리자에게 작업 종료 알림이 간다.","저장 공간이 가득 차 실패하면 실패 사유는 「스토리지 부족」이다.","실패 뒤 [발행]은 「마지막 전체 실행이 실패해 발행할 실행 결과가 없습니다.」로 막힌다.","다만 실패한 실행은 실패한 노드부터 이어서 실행할 수 없고, 처음부터 다시 실행한다.","이어서 실행은 중간 산출물을 보관하고 중지한 실행에만 있다.","필터 조치나 AI 단계의 실패 행 처리가 「실행 실패」이면 해당 행이 하나라도 생기는 순간 실행을 실패로 끝낸다.","출력 노드의 데이터 계약 검증을 통과하지 못해도 실행을 실패로 끝낸다.","실행이 끝나면 작업 이력에 실행 줄(실행 조건, 결과, 실행 시간)과 소스 노드가 읽은 파일·회차 줄을 남긴다.","데이터 파이프라인은 원본 데이터에 쓰지 않고, 소스는 실행을 시작할 때의 최신 회차를 읽는다."]},{"제목":"실행 일정","문장":["실행 일정은 외부 소스 단계(웹 크롤링, 데이터베이스 조회, 외부 서버 파일)가 있는 수집 노드에만 걸고, 처음 값은 비활성화다.","주기는 매시간, 매일, 매주, 매달, 매년이다.","시각은 매시간이면 매시 00·10·20·30·40·50분 가운데 하나, 그 밖의 주기는 00:00~23:00 정시 가운데 하나다.","매주, 매달, 매년은 배포 일시의 요일과 날짜를 따른다.","파이프라인이 배포중일 때만 정한 시각에 전체 실행을 처음부터 시작하고, 실행 줄의 실행 조건은 「실행 일정」이다.","수집 노드가 여럿이면 노드마다 계산한 시각 가운데 가장 이른 시각이 다음 실행 일시다.","다음 실행을 기다리는 동안 상태는 대기이고, 자원을 이미 점유하므로 자원 대기 작업 수에 세지 않는다.","배포하지 않은 동안 지나간 시각은 나중에 몰아서 실행하지 않고, 작업 이력에도 남기지 않는다.","일정을 바꾸면 [편집 완료] 때 작업 이력에 「설정 변경」 한 줄이 남고, 다음 실행부터 적용된다.","다만 그 시각에 앞 전체 실행이 진행 중이거나, 발행 중이거나, 다른 구성원이 편집 중이면 이번 일정은 건너뛴다.","건너뛰면 작업 이력에 「건너뜀」 한 줄과 이유를 남긴다.","발행하지 않은 실행 결과에 검수 판정이 있으면 이번 일정을 건너뛰고 생성자와 관리자에게 알린다.","발행하지 않은 실행 결과에 검수 판정이 없으면 일정 실행이 그 결과를 새 실행 결과로 대체한다.","데이터 파이프라인 전체에 거는 일정은 없고, 정해진 시각의 실행은 수집 노드 실행 일정으로만 한다."]},{"제목":"라벨링 대기와 검수","문장":["전체 실행이 라벨링 단계에 닿으면 라벨링 대기로 멈추고, 작업자와 검수자에게 검수 요청 알림을 보낸다.","라벨링 대기 동안 상태는 실행중을 유지하고 실행 자원은 돌려준다.","작업자가 배정된 항목을 모두 저장하면 시스템이 배포한 실행 자원을 다시 받아 실행을 이어 간다.","다시 받을 자원이 모자라면 자원이 돌아올 때까지 기다렸다가 자원 배정 차례대로 이어 간다.","라벨링 대기 중에도 [실행 중지]로 멈출 수 있고, 입력한 라벨은 보관해 다음 이어서 실행에서 쓴다.","라벨은 고친 뒤 1초가 지날 때와 항목을 옮길 때 자동 저장하고, 라벨 저장 한 건이 작업 이력 한 줄이다.","검수자는 저장된 항목을 승인, 반려, 보류로 판정하고, 판정은 즉시 실행 결과에 반영되며 한 건마다 작업 이력에 한 줄이 남는다.","검수자를 정하지 않았으면 작업자가 저장한 항목을 바로 승인한다.","표본 검수 n% 이면 작업을 완료할 때마다 그 항목을 n% 확률로 표본에 넣고, 표본에 들지 않은 항목은 자동 승인한다.","반려한 행은 이번 버전에서 빠지고, 다음 전체 실행 때 재작업 항목으로 다시 라벨링 대기가 된다.","다만 미판정이나 보류가 한 건이라도 남아 있으면 [발행]이 막힌다.","이미 발행한 결과의 판정은 바꿀 수 없고, 판정 되돌리기는 발행 전까지만 한다.","새 전체 실행이 시작되면 지난 판정은 지워지고, 승인한 라벨 값은 남지만 다시 검수 대상이 된다.","검수자를 정하지 않은 파이프라인의 격리 행은 자동 승인하지 않고 버전에서 뺀다."]},{"제목":"발행","문장":["검수 대기가 0건인 실행 결과에서 [발행]하면 결과 확인, 파일 이동, 버전 등록 세 단계로 데이터셋 버전 vN 을 만든다.","발행은 화면을 닫거나 새로 고쳐도 계속되고, 다시 열면 「데이터셋 버전 vN을 발행하고 있습니다. {단계} 중입니다(n/3).」가 보인다.","버전 폴더는 버전 등록 단계가 끝날 때 데이터 관리에 처음 생기고, 기본 저장 폴더는 /데이터셋/{파이프라인 이름}이다.","발행하는 동안 [전체 실행], [편집], 삭제를 막는다.","발행은 실행 결과를 버전 폴더로 옮기는 일이라 스토리지 사용량이 늘지 않고, 잔여 스토리지를 검사하지 않는다.","저장 폴더에 같은 vN 폴더가 이미 있으면 시작 전에 [발행]을 막는다.","실행 결과를 만든 뒤 원본 데이터가 바뀌었으면 그 결과는 발행할 수 없다.","실행 결과가 0행이면 발행을 막는다.","권한과 배포 상태는 발행 조건이 아니다.","발행은 회차를 새로 열지 않고 그 배포 회차의 작업 이력에 「데이터셋 버전 발행」 한 줄을 남긴다.","다만 [발행 취소]를 하거나 발행이 도중에 실패하면 버전과 버전 폴더를 만들지 않고, 실행 결과와 검수 판정은 남긴다.","발행이 실패하면 실행자와 관리자에게 작업 종료(실패) 알림을 보내고, 다시 [발행]하면 같은 결과로 처음부터 발행한다."]},{"제목":"데이터셋 버전과 쓰는 작업","문장":["발행한 버전을 고쳐 저장하면 새 버전 vN+1 이 되고 원래 버전은 그대로 남는다.","새 버전이 생기면 그 데이터셋을 쓰는 작업마다 생성자와 관리자 전원에게 「데이터셋 새 버전」 알림을 한 건 보낸다.","파인 튜닝은 쓰던 버전을 자동으로 바꾸지 않고, 학습·테스트 데이터셋마다 「최신 vM이 있습니다.」와 [vM으로 변경]을 보인다.","파인 튜닝의 버전은 다음 실행 때 사람이 [vM으로 변경]으로 바꾼다.","지식베이스는 새 버전으로 자동으로 바뀌지만 [검색 DB 업데이트] 전까지는 이전 버전으로 검색한다.","지식베이스 평가셋과 Custom 벤치마크는 쓰던 버전을 고정하고 「최신 vM이 있습니다.」만 알린다.","모델 배포 벤치마크는 저장한 결과의 버전을 그대로 둔다.","다만 쓰는 작업이 없는 버전도 자동으로 지우지 않고 개수 상한도 두지 않는다.","버전 정리는 사람이 데이터 관리에서 하고, 쓰는 작업이 있는 버전 폴더는 지울 수 없다.","지식베이스 평가셋과 저장하기 전 Custom 벤치마크가 고정해 쓰는 버전은 지울 수 있고, 지우면 그 설정에 「삭제됨」을 보인다.","버전 사용 현황은 데이터셋이 아니라 버전마다 센다."]},{"제목":"설정 편집과 실행 결과 삭제","문장":["설정 탭에서 [편집]을 누르는 순간 편집자가 되고 [편집 완료]로 끝나며, 정보 탭 수정과 같은 점유 하나다.","바꾼 설정은 바로 자동 저장되고 다음 전체 실행부터 반영된다.","배포 중에도 설정을 편집할 수 있다.","다만 전체 실행 중(라벨링 대기 포함)과 발행 중에는 [편집]을 막는다.","[편집 완료] 때 설정이 처음과 달라졌으면 발행하지 않은 실행 결과와 그 검수 판정을 지운다.","이때 「설정이 변경되어 발행하지 않은 실행 결과를 삭제했습니다.」를 알리고, 이미 발행한 버전은 지우지 않는다.","편집 모드만 열고 바꾸지 않았으면 실행 결과를 지우지 않는다.","3분 동안 조작이 없어 편집이 끝나도 [편집 완료]와 같이 처리하고, 설정이 바뀌었으면 같은 규칙으로 실행 결과를 지운다.","설정 롤백은 고른 버전을 발행한 시점의 설정으로 지금 설정을 바꾸고, 바뀐 설정은 다음 전체 실행부터 반영한다.","롤백으로 설정이 바뀌어도 데이터셋 버전과 작업 이력은 지우지 않는다."]},{"제목":"표본 실행","문장":["표본 실행은 배포중일 때만 하고, 소스부터 고른 노드까지 원본 일부를 배포한 자원으로 처리해 미리보기에 보인다.","표본 실행은 데이터셋 버전을 만들지 않고 원본 데이터에 적재하지 않는다.","표본 크기는 표 소스 100·500·1,000행, 파일 소스 20·50·100개 가운데 고른다.","표본 실행은 한 번에 하나만 하고, 전체 실행 중에는 막는다.","표본 실행 중지는 확인 없이 멈추고 그때까지의 표본 결과는 버린다.","표본 실행은 회차 번호 없이 지금 배포 회차의 작업 이력 한 줄로 남는다."]},{"제목":"삭제와 복제","문장":["배포가 걸려 있는 동안(대기, 설치중, 배포중, 실행중) 데이터 파이프라인 삭제를 막는다.","발행 중, 표본 실행 중, 편집 모드, 다른 구성원 편집 중에도 삭제를 막고 먼저 걸린 이유 하나를 보인다.","삭제하면 설정과 작업 이력을 지우고, 발행한 데이터셋 버전 폴더는 데이터 관리에 일반 데이터셋 폴더로 남는다.","발행한 데이터셋을 파인 튜닝이 쓰고 있어도 파이프라인 삭제는 막지 않는다.","복제는 설정만 복사하고 실행 결과, 버전, 작업 이력은 복사하지 않는다."]}]},{"주제":"컴퓨팅 자원과 대기","개요":"할당량 안에서 작업이 자원을 받거나 기다리는 규칙, 배정 차례, 대기 알림과 취소, 예약, 회수와 확장, 할당량 변경 반영, 사용량 집계를 다룬다.","묶음":[{"제목":"자원 부족 대기 진입","문장":["사용자가 배포나 학습 실행을 눌렀을 때 노드 풀의 남은 GPU 가 요청보다 적으면 작업은 대기(자원 부족)가 된다.","대기하는 동안 자원은 하나도 잡지 않는다.","대기 사유 창에는 실행 시점, 대기 사유, 필요한 자원, 실행 예정 일시, 대기 시간이 보인다.","즉시 실행의 실행 예정 일시는 「GPU 반환 시」이고, 대기 차례와 예상 대기 시간은 보이지 않는다.","GPU 는 있는데 CPU 나 RAM 이 모자라도 사유는 「자원 부족」이고 문장에 모자란 자원을 적는다.","다만 요청이 그 노드 풀의 GPU 총량보다 크면 대기에 들어가지 않고 처음부터 막으며 「이 풀의 GPU는 모두 n EA입니다.」를 보인다.","대기 사유는 자원 부족, 예약, 피크외 시간, 승인 대기 넷이다.","자원 대기 작업 수는 승인 대기를 빼고 세고, 승인되는 순간부터 센다.","자원 대기 중이거나 예약된 학습은 설정을 고칠 수 없고, [실행 취소] 뒤 고친다."]},{"제목":"자원 배정 차례","문장":["노드 풀에 자원이 반환되면 시스템은 같은 풀의 대기 작업에 대기를 시작한 차례대로 자원을 배정하고 바로 시작한다.","다만 앞 작업이 반환된 자원에 들어가지 못하면 그 자원에 들어가는 뒤 작업을 먼저 시작한다.","배정 차례는 회수로 대기에 돌아간 구성 요소, 오토 스케일링 확장, 새 배포·학습 순이다.","대기에는 만료가 없고, 대기 사유가 모두 풀리면 자동으로 실행한다."]},{"제목":"대기 알림과 사유 변경","문장":["자원 부족으로 대기에 들어가는 순간 실행자와 관리자에게 자원 대기 알림을 한 번 보낸다.","대기가 장기 자원 대기 알림 기준(처음 값 24시간)을 넘으면 실행자와 관리자에게 한 번 더 보낸다.","그 뒤로는 대기가 이어져도 반복해서 보내지 않는다.","장기 자원 대기 알림 기준은 관리자가 시스템 설정 운영 설정에서 1~72시간 사이로 바꾸고, [저장] 뒤 다음 판정부터 적용된다.","대기 사유가 승인 대기나 예약에서 자원 부족으로 바뀌면 작업 이력에 「시스템」 줄만 남기고 알림은 보내지 않는다."]},{"제목":"대기 취소","문장":["대기는 자원이 확보되거나 사람이 취소할 때만 끝난다.","자원 대기와 예약의 취소는 실행자와 관리자만 할 수 있고, 권한 없이 확인 창 뒤 바로 된다.","다른 구성원에게는 취소 버튼이 비활성이고 「실행자와 관리자만 취소할 수 있습니다.」를 보인다.","배포 대기를 취소하면 중지가 되고, 학습 대기를 취소하면 대기 직전 상태로 돌아간다.","잡은 자원이 없으므로 취소할 때 돌려줄 자원은 없다.","다만 확인 창을 연 사이 자원이 잡혀 설치가 시작되었어도, 확인하면 설치를 취소하고 중지로 처리한다.","대기 중에 노드 풀 할당이 줄어 요청이 풀 총량보다 커지면 시스템이 대기를 끝내고 실패로 두며 사유는 「노드 풀 총량 초과」다.","이때 실행자와 관리자에게 알린다."]},{"제목":"예약과 반복 예약","문장":["예약 시각에 자원이 충분하면 바로 실행하고, 모자라면 자원 대기로 바뀌어 자원이 돌아오는 순간 시작한다.","이때 실행 예정 일시는 「GPU 반환 시(예약 일시 …)」로 보인다.","종료 시각에 이르면 시스템이 배포를 중지한다.","데이터 파이프라인은 종료 시각에 진행 중인 전체 실행이 있으면 그 실행이 끝난 뒤 중지한다.","반복 예약(매일, 매주)은 한 번 끝나면 다음 예약 대기로 돌아간다.","다만 자원 대기로 바뀐 뒤 종료 시각까지 시작하지 못하면 종료 시각에 대기를 끝내고 중지로 둔다.","다음 반복 시각에 앞 반복이 아직 대기나 실행 중이면 이번 반복은 건너뛰고 작업 이력에 「건너뜀」을 남긴다.","배포 중에 [배포 중지]를 하면 남은 반복 예약도 함께 지운다.","피크외 시간 대기는 GPUBASE 가 배정한 일시에 실행하고, 그때 자원이 모자라면 자원 대기로 바뀐다.","피크외 시간 배정이 오지 않으면 피크외 시간 대기를 유지하고, 실행 예정 일시는 「배정 전」이다."]},{"제목":"회수와 오토 스케일링 확장","문장":["오버쿼터 회수로 구성 요소가 내려가면 그 구성 요소는 실패가 아니라 대기로 돌아간다.","자원이 반환되면 시스템이 그 구성 요소를 자동으로 다시 배포한다.","구성 요소가 회수되어 대기하는 동안 상위 에이전트는 배포중을 유지한다.","오토 스케일링으로 레플리카를 늘려야 하는데 자원이 모자라면 기존 레플리카로 계속 서비스한다.","늘리지 못한 레플리카는 대기했다가 자원이 반환되면 자동으로 늘린다.","모델 배포가 점유하는 GPU 는 레플리카 수 × 레플리카 1개의 GPU 다."]},{"제목":"할당량 변경","문장":["할당량은 GPUBASE 가 정하고, GPUBASE 에서 승인되는 순간 바뀐다.","AI 개발자는 [자원 한도 변경 요청]으로 자원별 요청 할당량과 메모를 보내고, 결과는 알림으로 받는다.","요청 할당량은 지금 쓰고 있는 자원보다 작게 넣을 수 없다.","바꾼 자원이 없으면 [요청]을 막는다.","관리자는 요청하지 않고 GPUBASE 에서 직접 바꾸며, 관리자에게 [자원 한도 변경 요청]은 비활성이다.","AGENTBASE 관리자는 이 요청을 검토하지 않고, 검토할 요청과 구성원별 승인 대기 수에도 넣지 않는다.","승인 대기 요청은 구성원마다 1건이고, 다른 구성원의 요청이 대기해도 내 요청은 막지 않는다.","승인 대기 중인 요청은 요청자 본인이 [자원 한도 변경 요청 취소]로 취소한다.","요청, 취소, 승인, 거절은 감사 이력에 남고 처리자는 GPUBASE 다.","다만 GPUBASE 가 스토리지 할당량을 지금 사용량보다 작게 줄여도 데이터는 지우지 않는다.","이때 사용률은 100% 를 넘겨 표시하고, 새 생성을 막고 진행 중인 업로드를 실패로 끝낸다.","할당량이 사용량보다 작아지면 관리자에게 조치가 필요한 저장 용량 알림을 보낸다.","사람이 정리해 사용률이 95% 아래로 내려가면 차단이 풀린다."]},{"제목":"자원 사용량 집계","문장":["컴퓨팅 자원 사용량은 자원을 점유한 작업이 요청한 양의 합이다.","스토리지 사용량은 작업이 저장한 산출물과 올린 파일 용량의 합이다.","실패한 작업은 자원을 반환하므로 사용량과 점유에 넣지 않는다.","작업 자원은 GPU 를 쓰면 GPU, CPU, RAM 을 모두 적고, 쓰지 않으면 CPU 와 RAM 만 적는다.","사용 이력의 집계 단위는 기간이 7일 이하면 1시간, 7일을 넘으면 1일이다.","자원 현황은 모든 구성원이 조회한다."]}]},{"주제":"파운데이션 모델 학습","개요":"베이스 모델을 데이터셋으로 파인 튜닝하고, 학습 중 저장한 체크포인트를 커밋으로 확정해 모델 배포에 넘기는 동작을 다룬다.","묶음":[{"제목":"작업 생성과 베이스 모델 불러오기","문장":["구성원이 이름, 설명, 타입, 베이스 모델, 학습 프레임워크, 학습 방식을 정해 [생성]하면 작업은 생성됨 상태로 만들어진다.","생성은 권한이 필요 없고 자원을 잡지 않는다.","타입은 LLM, VLM 둘이다.","생성하면 시스템이 베이스 모델 불러오기를 바로 시작하고, 불러오기가 끝나야 [실행]이 열린다.","불러오기가 끝나거나 실패하면 작업 종료 알림을 보낸다.","다만 불러오기가 실패하면 [실행]은 계속 막힌다.","생성할 때 기본 커밋 하나가 함께 저장된다.","베이스 모델, 학습 프레임워크, 학습 방식, 양자화는 생성 뒤 바꿀 수 없다.","스토리지 사용률이 95% 이상이면 새 작업 생성을 막는다.","커밋 목록에서 [이 커밋으로 모델 생성]을 하면 그 커밋을 시작점으로 고정한 새 작업이 종료 상태로 만들어진다.","다른 AGENTBASE의 커밋 파일(.zip)로 생성하면 시스템은 작업을 먼저 만든 뒤 업로드를 이어서 한다.","업로드가 끝나면 커밋을 커밋 목록에 더하고 베이스 모델을 불러온다.","다만 업로드를 중지하거나 업로드가 실패하면 커밋 없이 베이스 모델만 남긴다.","다만 커밋 파일의 베이스 모델을 이 AGENTBASE가 제공하지 않으면 [생성]을 막는다."]},{"제목":"학습 설정 저장과 잠금","문장":["데이터셋을 고르면 시스템이 앞, 중간, 뒤 일부 행에 학습 데이터 형식 일곱을 적용해 통과한 행 수를 보여 준다.","통과한 행이 있는 형식만 고를 수 있고, 통과한 형식이 없는 데이터셋은 고를 수 없다.","고른 데이터셋 버전은 고정되고, 새 버전이 생겨도 자동으로 따라가지 않는다.","데이터셋에 새 버전이 생기면 작업 생성자와 관리자에게 데이터셋 새 버전 알림을 보낸다.","학습이 쓰는 데이터셋 버전은 데이터 관리에서 지울 수 없다.","학습 설정은 [저장]해야 다음 실행에 반영되고, 저장하지 않은 변경이 있으면 [실행]을 막는다.","Test Steps는 Train Logging Steps의 배수, Checkpoint Steps는 Test Steps의 배수로 시스템이 맞춘다.","대기, 설치중, 실행중이거나 실행 요청이 승인을 기다리는 동안에는 학습 설정을 바꿀 수 없다.","다른 구성원이 편집 중이면 학습 설정, [실행], [커밋], 커밋 불러오기, 커밋 수정과 삭제를 막는다.","편집 점유는 작업 하나에 한 명이고, 편집자가 3분 동안 조작하지 않으면 풀린다."]},{"제목":"학습 실행과 자원 대기","문장":["구성원이 실행 자원과 실행 시점(즉시, 예약, 피크외 시간)을 정해 [실행]하면 자원이 있을 때 설치중을 거쳐 실행중이 된다.","자원(노드 풀, GPU, CPU, RAM)은 설치중에 잡고 종료, 중지, 실패 때 돌려준다.","컴퓨팅 자원 사용 권한이 없으면 [실행 요청]을 보내고, 관리자가 승인하면 요청한 자원과 실행 시점으로 실행한다.","실행하면 커밋하지 않은 지난 체크포인트와 지표가 지워지므로 시스템은 실행 전에 확인 창으로 알린다.","학습을 시작할 때 전체 행을 다시 검사해 형식을 통과하지 못한 행은 빼고 학습하며, 뺀 행 수를 작업 이력에 남긴다.","스토리지 사용률이 95% 이상이면 [실행]을 막는다.","자원 부족, 예약, 피크외 시간, 승인 대기이면 학습은 대기 상태가 되고, 대기 중에는 자원을 잡지 않는다.","대기는 만료가 없고, 자원 반환, 예약 시각, GPUBASE가 배정한 시각, 승인 가운데 해당 조건이 되면 시스템이 자동으로 시작한다.","반환된 자원은 대기 시작 순서대로 배정하고, 앞 작업이 들어가지 못하면 그 자원에 들어가는 뒤 작업에 먼저 배정한다.","자원 배정 차례는 회수로 대기에 돌아간 작업, 오토 스케일링 확장 대기, 새 배포와 학습 대기 순이다.","대기에서 자동으로 시작하면 실행자와 관리자에게 작업 시작 알림을 보낸다.","자원 부족 대기에 들어가면 실행자와 관리자에게 한 번 알린다.","자원 부족 대기가 기준 시간(처음 값 24시간, 시스템 설정)을 넘으면 실행자와 관리자에게 한 번 더 알린다.","한 대기 안에서 대기 사유가 바뀌면 작업 이력에 시스템 줄만 남기고 알리지 않는다.","대기 중에는 학습 설정을 고칠 수 없고 작업 삭제도 막힌다.","[실행 취소]를 하면 확인 뒤 바로 대기를 끝내고 대기 직전 상태(생성됨, 종료, 중지, 실패)로 돌아간다.","[실행 취소]는 컴퓨팅 자원 사용 권한 없이 실행자와 관리자만 할 수 있다.","다만 승인 대기는 [실행 취소]가 아니라 요청자의 [요청 취소]로 끝낸다.","다만 예약 시각에 자원이 모자라면 자원 부족 대기로 바뀐다.","다만 취소 확인 창을 연 사이 설치가 시작되면 시스템은 설치를 취소하고 대기 직전 상태로 돌린다.","다만 요청한 GPU가 그 노드 풀의 GPU 총량보다 크면 대기에 넣지 않고 실행을 막는다.","다만 대기 중 노드 풀 할당이 줄어 요청이 풀 총량보다 커지면 대기를 끝내고 실패(노드 풀 총량 초과)로 둔다.","노드 풀 총량 초과로 실패하면 실행자와 관리자에게 알린다.","다만 승인하는 순간 예약 일시가 이미 지났으면 [승인]을 막는다."]},{"제목":"학습 회차","문장":["회차는 학습이 실행중에 들어가는 순간 열리고 종료, 중지, 실패로 닫힌다.","생성은 0회차이고, 권한 없이 요청한 실행은 승인 뒤 실행중에 들어갈 때 회차가 열린다.","회차가 열리면 모든 구성원에게 회차 시작 알림을 보낸다.","설치중에 시작이 실패하면 상태는 실패가 되고 회차는 열리지 않는다.","대기, 대기 취소, 설치중 실패는 회차 번호 없는 줄로 앞 회차의 작업 내역에 남는다.","작업 이력은 지우지 않고, 시스템 설정의 이력 표시 기간은 화면에 보이는 기간만 정한다.","리포트에는 표시 기간과 관계없이 모든 회차 기록이 들어간다."]},{"제목":"학습 지표와 체크포인트 보관","문장":["실행 중에는 진행률, 에포크, 스텝, 처리 속도, 경과 시간을 보이고 남은 시간은 계산하지 않는다.","Train Logging Steps에서 정한 스텝마다 지표 점 하나가 곡선에 더해진다.","Checkpoint Steps에서 정한 스텝마다 체크포인트가 저장되고 곡선에 저장 지점으로 표시된다.","학습 지표는 Loss(Train, Test), Perplexity(Train, Test), Grad Norm, Learning Rate, Generalization Gap, Token Accuracy 여덟이다.","저장한 체크포인트 수가 Checkpoint Keep(2~50개, 처음 값 2개)을 넘으면 시스템이 가장 오래된 것부터 지운다.","학습이 종료, 중지, 실패로 끝나면 커밋한 체크포인트와 마지막 체크포인트만 남기고 나머지를 지운다.","커밋하지 않은 체크포인트와 지표는 다음 학습을 실행할 때 지워진다.","다만 학습 기록을 읽지 못한 회차는 결과 불명으로 남고, [커밋]하면 산출물을 확인할 수 없다고 알린다."]},{"제목":"학습 중지와 실패","문장":["구성원이 실행 중인 학습을 [중지]하면 GPU를 바로 돌려주고 그 회차는 중지로 끝난다.","중지해도 마지막으로 저장한 스텝까지의 지표와 체크포인트가 남아 커밋할 수 있다.","컴퓨팅 자원 사용 권한이 없으면 학습 중지 요청을 보내고, 관리자가 승인하면 중지한다.","다만 이미 끝난 학습에 온 중지 요청은 실행하지 않는다.","학습 오류나 스토리지 부족으로 실패하면 자원은 자동으로 돌아가고 그 회차는 실패로 끝난다.","실패해도 마지막으로 저장한 체크포인트가 남아 커밋할 수 있다.","학습이 실패하면 실행자와 관리자에게 실패 알림을 보낸다.","중지나 실패 뒤 다시 [실행]하면 다음 회차가 열린다.","다음 실행은 커밋했으면 그 커밋에서 이어서 학습하고, 커밋하지 않았으면 불러온 커밋부터, 없으면 처음부터 학습한다."]},{"제목":"커밋 생성","문장":["학습이 종료되거나 중지된 뒤 저장된 체크포인트를 골라 이름과 설명을 붙여 [커밋]하면 커밋으로 저장한다.","한 회차 안에서 체크포인트마다 한 번씩, 여러 개를 커밋할 수 있다.","다만 이미 커밋한 체크포인트를 다시 커밋하면 「이미 커밋한 체크포인트입니다.」로 막는다.","커밋은 권한이 필요 없다.","저장이 끝나는 순간 커밋 목록에 올라 모델 배포에서 고를 수 있고, 작업은 그 커밋을 불러온 상태가 된다.","커밋을 저장하는 동안에는 [실행], 다른 커밋, 커밋 불러오기를 막는다.","설치중이나 실행중이면 커밋을 막는다.","스토리지 사용률이 95% 이상이면 커밋 저장을 막는다.","커밋은 그 회차의 작업 이력에 결과물 줄로 남고, 커밋하지 않은 회차는 「커밋 안 함」으로 남는다."]},{"제목":"커밋 불러오기(롤백)","문장":["커밋을 골라 [커밋 불러오기]하면 바로 학습하지 않고 다음 학습의 시작점과 학습 설정만 그 커밋으로 바뀐다.","시작점 변경은 작업 이력에 「반영 대기」로 남았다가 다음 회차가 시작되면 「n회차에 반영」으로 바뀐다.","커밋에서 이어서 학습할 때는 Learning Rate, Num Train Epochs, 데이터셋만 바꿀 수 있다.","어댑터 모양을 정하는 값(rank, alpha, 양자화)은 커밋 값으로 잠긴다.","커밋에서 이어서 학습할 때는 config 파일을 적용할 수 없다.","불러와도 커밋은 지워지지 않는다.","커밋하지 않은 체크포인트가 있으면 확인 창으로 묻고, 불러오면 그 체크포인트와 지표를 지운다.","다만 기본 커밋을 불러오면 다음 학습은 처음부터이고 항목 잠금이 없다.","대기, 설치중, 실행중, 승인 대기, 커밋 저장 중에는 불러오기를 막는다."]},{"제목":"커밋 수정, 삭제와 모델 배포 영향","문장":["커밋 이름과 설명을 바꾸면 바로 보인다.","배포중인 모델 배포가 쓰는 커밋은 이름과 설명을 고칠 수 없다.","중지된 모델 배포가 쓰는 커밋의 이름을 바꾸면 그 배포의 생성자와 관리자에게 연결 자원 변경 알림을 보낸다.","모델 배포가 하나라도 쓰는 커밋은 배포 상태와 관계없이 지울 수 없다.","모델 배포가 다른 커밋으로 바꾸면 그 순간부터 앞 커밋을 지울 수 있다.","대기 중이거나 실행 중인 학습이 이어서 학습하는 커밋은 학습이 끝나거나 중지될 때까지 지울 수 없다.","불러온 커밋을 지우면 작업은 기본 커밋을 불러온 상태로 돌아간다.","기본 커밋은 수정, 삭제, 다운로드할 수 없다.","커밋 다운로드는 다운로드 권한이 필요하고, 없으면 요청 뒤 승인되면 요청자가 1회 받는다.","다운로드 승인은 7일이 지나면 만료되고, 요청할 때의 커밋 목록에만 적용된다.","이 작업의 커밋을 쓰는 모델 배포가 있거나 대기, 실행중, 승인 대기이면 작업 삭제를 막는다.","작업을 삭제하면 체크포인트와 커밋을 함께 지우고, 작업 이력은 리포트와 감사 이력에 남는다."]}]},{"주제":"모델 배포","개요":"모델을 레플리카로 실행해 에이전트, 지식베이스, 데이터 파이프라인이 부르게 하고, 자원 변경, 버전 교체, 장애 복구, 평가와 리더보드를 다룬다.","묶음":[{"제목":"생성과 배포 상태","문장":["구성원이 모델 배포를 생성하면 자원을 잡지 않은 생성됨 상태로 만들어진다.","[배포]하면 자원이 있을 때 설치중(자원 받기, 모델 적재)을 거쳐 배포중이 되고, 그 순간 배포 회차가 열린다.","컴퓨팅 자원 사용 권한이 없으면 [배포 요청]을 메모와 함께 보내고, 승인 뒤 요청한 자원과 실행 시점으로 진행한다.","요청이 거절되거나 취소되면 요청 전 상태로 돌아가고, 요청 취소는 요청자 본인만 한다.","실행 시점은 즉시 실행, 지정 시각(한 번, 매일, 매주와 종료 시각), 피크외 시간이다.","자원 부족, 예약, 피크외 시간, 승인 대기이면 대기 상태가 되고, 대기 규칙은 학습 대기와 같다.","설치중에 시작이 실패하면 실패 상태가 되고, 회차는 열리지 않으며 자원은 자동으로 돌아간다.","자원 회수로 레플리카가 내려가면 대기로 돌아가고, 자원이 반환되면 시스템이 자동으로 다시 배포한다.","다만 예약 시각에 자원이 모자라 종료 시각까지 시작하지 못하면 대기를 끝내고 중지로 둔다.","다만 반복 예약의 다음 일시에 앞 반복이 대기 중이거나 배포 중이면 이번 반복을 건너뛰고 「건너뜀」 줄을 남긴다.","외부 엔드포인트와 상용 API는 생성할 때 접속을 확인하고, 성공하면 자원 없이 바로 배포중으로 등록한다.","외부 엔드포인트와 상용 API는 권한, 자원, 실행 시점, 오토 스케일링을 거치지 않는다.","다만 접속 확인에 실패하면 외부 엔드포인트와 상용 API는 저장을 막는다.","Base URL이나 API Key를 고쳐 저장하면 저장할 때 접속을 다시 확인하고, 실패하면 저장을 막는다.","API Key는 가려서 보이고 작업 이력에도 값을 남기지 않는다."]},{"제목":"배포 중 자원과 설정 변경","문장":["실행 단위는 레플리카이고, 점유 GPU는 레플리카 수에 레플리카 1개의 GPU를 곱한 값이다.","레플리카 1개의 자원(노드 풀, GPU, CPU, RAM)과 추론 엔진 설정은 [배포]할 때 정한다.","배포중에는 컴퓨팅 자원과 추론 엔진 설정(KV 캐시 비율, 최대 배치 크기)을 고칠 수 없다.","처리량은 오토 스케일링으로 레플리카 수를 늘려 높인다.","GPU 수와 그 밖의 자원 값은 배포를 중지한 뒤 다시 [배포]할 때 바꾸고, 시스템은 마지막 자원 값을 채워 둔다.","레플리카는 최대 16개이고, 오토 스케일링을 쓰지 않으면 1개다.","등록 유형, 타입, 모델은 생성 뒤 바꿀 수 없다.","AGENTBASE 모델 배포의 커밋은 생성 뒤에도 버전 교체로 바꿀 수 있다."]},{"제목":"모니터링 지표 수집","문장":["LLM, VLM, Embedding, Reranker 타입은 지표를 15초마다 수집한다.","STT, TTS, Image Generation 타입과 외부 엔드포인트, 상용 API는 지표를 1분마다 집계한다.","배포중이 아니면 지표를 수집하지 않는다.","호출이 없어도 배포중이면 GPU, CPU, RAM 사용률은 계속 수집한다.","외부 엔드포인트와 상용 API에는 자원 사용률이 없다.","호출은 성공 응답을 정상, 권한 거부와 호출 한도 초과를 경고, 요청 오류와 서버 오류를 에러로 센다.","오토 스케일링에 따른 레플리카 수 변화는 모니터링에만 담고 작업 이력에는 남기지 않는다."]},{"제목":"오토 스케일링 판정","문장":["스케일링 기준은 LLM, VLM이 포화도(처음 값 80%)와 대기 요청(처음 값 4건), 그 밖의 타입이 GPU 사용률(처음 값 70%)이다.","레플리카 평균이 기준값을 확장 지속 시간(처음 값 1분, 30초~1시간) 이상 넘으면 레플리카를 1개 늘린다.","레플리카 평균이 기준값의 절반 미만으로 축소 지속 시간(처음 값 5분, 1분~6시간) 이상 이어지면 1개 줄인다.","레플리카를 늘린 뒤에는 확장 후 대기 시간 동안 판정을 보류한다.","최소 레플리카는 1~15개, 최대 레플리카는 최소보다 크고 16개 이하다.","활성화, 최소 올림, 최대 올림은 컴퓨팅 자원 사용 권한을 거치고, 권한이 없으면 요청 뒤 승인 즉시 저장한다.","비활성화, 낮춤, 기준과 지속 시간 변경은 권한과 확인 창 없이 바로 저장한다.","배포 중에 오토 스케일링을 비활성화하면 바로 해제하고 지금 레플리카 수를 유지한다.","오토 스케일링은 대기, 설치중, 배포중에서만 쓰고, 외부 엔드포인트와 상용 API는 쓸 수 없다.","다만 확장할 자원이 없으면 기존 레플리카로 계속 응답하고, 자원이 반환되면 1개 늘린다.","확장 대기는 상태를 바꾸지 않고 작업 이력에 남기지 않는다.","다만 확장 대기 중 부하가 내려가거나 오토 스케일링을 비활성화하면 확장 대기를 끝낸다.","다만 승인하는 순간 요청 값이 지금 값보다 낮아졌으면 [승인]을 막는다."]},{"제목":"레플리카 축소와 처리 중인 요청","문장":["오토 스케일링 축소나 롤링 업데이트로 내릴 레플리카에는 시스템이 새 요청을 배정하지 않는다.","내릴 레플리카는 처리 중인 요청이 끝난 뒤 내린다.","처리 중인 요청을 기다리는 상한은 60초(시스템 설정 처음 값)이다.","상한이 지나면 남은 요청을 끊고 레플리카를 내리며, 끊긴 요청은 에러로 센다."]},{"제목":"버전 교체와 롤링 업데이트","문장":["롤링 업데이트는 사용 여부 하나만 정하고, 최대 추가 수, 최대 중단 수, 준비 대기 시간은 받지 않는다.","롤링 업데이트를 쓰는 배포의 버전을 바꾸면 새 레플리카 1개를 띄워 준비되면 이전 레플리카 1개를 내리기를 끝까지 되풀이한다.","교체하는 동안 호출은 멈추지 않는다.","교체하는 동안에는 레플리카 1개만큼 자원이 더 필요하다.","진행 중인 교체를 멈추는 조작은 없고, 교체는 끝나거나 실패할 때까지 진행한다.","교체가 끝나면 이 모델을 쓰는 에이전트는 다시 배포하지 않고 그 뒤의 호출부터 새 버전을 부른다.","버전 교체는 회차를 바꾸지 않고, 작업 이력에 「모델 버전 | 롤링 업데이트 | 이전 → 새」 줄로 남는다.","교체가 끝나면 작업 종료 알림을 보내고, 연결한 에이전트의 생성자와 관리자에게 연결 자원 변경 알림을 보낸다.","다만 교체에 필요한 추가 자원이 모자라면 기존 레플리카로 계속 응답하고, 자원이 반환되면 교체를 시작한다.","교체 대기는 상태를 바꾸지 않고 확장 대기와 같은 배정 차례를 따른다.","다만 새 버전 레플리카가 시작에 실패하면 새로 띄운 레플리카를 내리고 바꾼 레플리카도 기존 버전으로 되돌린다.","되돌린 뒤에는 기존 버전으로 계속 응답하고 생성자와 관리자에게 실패 알림을 보낸다.","롤링 업데이트를 쓰지 않으면 배포를 중지한 뒤 새 버전으로 다시 실행하고, 그동안 호출에 응답하지 못한다.","다만 배포중인 에이전트가 쓰는 모델 배포는 롤링 업데이트를 끈 채 버전을 바꿀 수 없다.","대기 중이거나 설치 중인 배포, 평가 중인 배포는 버전을 바꿀 수 없다."]},{"제목":"레플리카 장애와 자동 복구","문장":["레플리카가 응답하지 않으면 시스템이 1분 간격으로 3번까지 자동으로 다시 시작한다.","다시 시작에 성공하면 배포중을 유지하고 회차도 그대로이며, 생성자와 관리자에게 자동 복구 알림을 보낸다.","3번 모두 실패하면 상태를 실패로 바꾸고 자원을 반환하며 그 회차를 닫는다.","실패로 바뀌면 생성자와 관리자에게 중단 알림을 보낸다.","응답 없음과 복구는 작업 이력에 실행자 없는 시스템 줄로 남는다.","외부 엔드포인트와 상용 API가 응답하지 않으면 1분 간격으로 3번까지 다시 연결한다.","다시 연결되면 배포중을 유지하고 생성자와 관리자에게 자동 복구 알림을 보낸다.","3번 모두 실패하면 실패로 바꾸고 중단 알림을 보낸다.","실패 상태에서 [배포]하면 접속을 다시 확인해 성공하면 배포중, 실패하면 실패를 유지하고 사유를 시스템 로그에 남긴다."]},{"제목":"배포 중지","문장":["[배포 중지]는 권한과 관계없이 확인 뒤 바로 중지하고, 배포 중지 요청은 없다.","레플리카가 1개이면 모두 중지하고 GPU를 반환하며 회차를 닫는다.","레플리카가 2개 이상이면 「모두 중지」와 「레플리카 1개 유지」 가운데 고른다.","「레플리카 1개 유지」는 엔드포인트를 살린 채 나머지 GPU만 반환하고 오토 스케일링을 비활성화한다.","배포 중에 중지하면 남은 반복 예약도 지운다.","중지해도 모델과 설정은 남고 [배포]로 다시 실행한다.","오케스트레이터에 연결된 모델 배포는 GPUBASE에서 연결을 해제하기 전까지 중지할 수 없다.","평가 중이거나 다른 구성원이 편집 중이면 [배포 중지]를 막는다.","배포중인 에이전트가 직접 부르거나, 그 에이전트가 연결한 지식베이스가 쓰는 모델 배포는 중지할 수 없다.","다만 대기나 예약 중의 [배포 중지]는 대기와 예약을 취소하며, 실행자와 관리자만 한다.","에이전트 밖 지식베이스나 데이터 파이프라인이 쓰던 배포를 중지하면 그 검색 DB 생성과 파이프라인 실행은 그 단계에서 실패한다."]},{"제목":"벤치마크 평가","문장":["평가는 LLM, VLM 타입이 배포중일 때만 실행하고 권한이 필요 없다.","측정 조건은 사고 모드 사용 안 함, 반복마다 1회 생성, 3회 반복 평균으로 고정이다.","평가가 끝나면 결과는 저장하지 않은 결과로 남고, 이름을 넣어 저장해야 결과 목록에 남는다.","평가 중에는 이 배포의 배포 중지, 버전 교체, 삭제를 막는다.","[평가 중지]하면 완료한 데이터셋의 결과를 남길지 고른다.","남기면 완료한 데이터셋만 담은 결과가 중지 상태로 남고 이름을 넣어 저장한다.","완료한 데이터셋이 0개이면 결과를 남길 수 없다.","제공 벤치마크를 모두 측정하지 못한 결과는 종합 점수가 없다.","저장하지 않은 결과가 있을 때 다시 실행하면 확인 뒤 그 결과를 지운다.","다만 평가 도중 모델 배포가 실패하면 평가도 실패로 끝나고, 완료한 데이터셋의 결과를 남길지 중지와 같게 고른다.","다만 작업 관리에서 평가를 중지하면 결과를 남기지 않는다.","평가 실행, 중지, 결과 저장은 작업 이력에 평가 줄로 남는다."]},{"제목":"리더보드 등록과 해제","문장":["리더보드에는 제공 벤치마크 10개를 모두 측정하고 종료해 저장한 결과만 등록할 수 있다.","모델 배포마다 결과 하나만 등록하고, 이미 등록한 결과가 있으면 고른 결과로 바꾼다.","리더보드 등록 권한이 있으면 누르는 즉시 반영하고, 없으면 요청을 보내 승인 즉시 반영한다.","리더보드 줄은 평가할 때의 커밋과 점수로 고정되고, 버전을 바꿔도 점수는 그대로다.","새 버전의 점수는 다시 평가해 등록할 때 바뀐다.","등록한 결과는 배포 상태와 관계없이 리더보드에 남는다.","등록한 결과는 결과 목록에서 지울 수 없고, 먼저 등록을 해제해야 지울 수 있다.","[등록 해제]는 권한이 있으면 바로 내리고, 없으면 요청 뒤 관리자 승인으로 내린다.","대시보드에서 연 리더보드는 고른 모델 배포가 없어 [리더보드 등록]과 [등록 해제]가 비활성이다."]},{"제목":"삭제와 작업 이력","문장":["삭제는 권한을 거치지 않고 이름을 입력해 확인한다.","모델 배포를 삭제하면 평가 결과와 리더보드 등록을 함께 지우고, 삭제 창에서 이를 알린다.","리더보드에 등록한 결과가 있어도 삭제는 막지 않는다.","대기, 설치중, 배포중, 평가 중, 승인 대기 요청, 다른 구성원 편집 중이면 삭제를 막는다.","배포된 에이전트, 검색 DB가 있는 지식베이스, 실행 중인 데이터 파이프라인이 쓰는 모델 배포는 삭제를 막는다.","배포 전 에이전트나 검색 DB가 없는 지식베이스가 쓰던 배포를 지우면 그 참조는 「삭제됨」으로 남는다.","작업 이력은 최근 10회차(관리자가 3~50회차로 바꿈)를 보이고, 더 오래된 회차는 리포트에서 본다.","작업 이력과 시스템 로그는 지우지 않는다."]}]},{"주제":"지식베이스","개요":"문서를 청킹, 임베딩해 검색 DB 버전을 만들고 에이전트의 질의에 근거 문서를 돌려주며, 문서와 설정의 반영 시점, 버전, 평가, 검색 한도를 다룬다.","묶음":[{"제목":"배포와 자원","문장":["생성만 한 지식베이스는 자원을 잡지 않고, [배포]로 검색 컨테이너를 띄운 뒤 자원을 점유한다.","검색 DB 생성과 업데이트는 배포한 검색 컨테이너의 자원으로 실행하고 자원을 더 잡지 않는다.","[배포]와 오토 스케일링에서 자원을 늘리는 조작만 컴퓨팅 자원 사용 권한을 거친다.","검색 DB 생성, 문서와 설정 변경, 검색 테스트, 평가는 권한이 필요 없고, 문서 다운로드만 다운로드 권한을 거친다.","회차는 배포중에 들어간 순간 열리고 [배포 중지]나 실패로 닫히며, 검색 DB 생성은 그 회차 안의 작업이다.","배포를 중지했다가 다시 배포하면 회차는 오르고 검색 DB 버전은 그대로다.","[배포 중지]는 권한과 관계없이 확인 뒤 바로 중지하고, 검색 DB와 문서는 남는다.","평가나 평가셋 생성 중, 배포중인 에이전트가 연결함, 다른 구성원 편집 중이면 [배포 중지]를 막는다.","검색 컨테이너의 응답 없음이 이어지면 실패로 바뀌고 자원은 자동으로 돌아간다.","검색 컨테이너 오토 스케일링은 CPU 또는 RAM 사용률(처음 값 70%)을 기준으로 하고 규칙은 모델 배포와 같다.","자원 대기, 예약, 반복 예약 규칙은 모델 배포와 같다."]},{"제목":"문서 변경과 반영 시점","문장":["문서를 추가하면 반영 대기로 들어가고, 다음 검색 DB 생성이나 업데이트가 끝나는 순간 반영됨이 된다.","반영된 문서를 지우면 확인 뒤 삭제 대기가 되고, 다음 생성이 끝날 때까지는 검색에 그대로 쓰인다.","반영 대기 문서는 확인 없이 바로 지우고, 삭제 대기는 [삭제 취소]로 되돌린다.","문서 추가와 삭제는 검색 DB 생성 중이나 평가 중에도 막지 않고 다음 생성에 반영한다.","데이터 관리의 원본 데이터나 데이터셋이 새 회차나 버전이 되면 문서 표의 회차와 버전은 즉시 바뀐다.","그때 문서는 반영 대기가 될 뿐이고, 시스템은 검색 DB를 자동으로 다시 만들지 않는다.","그 데이터를 쓰는 작업의 생성자와 관리자에게 새 회차 알림을 보낸다.","다만 삭제한 문서를 근거로 저장된 응답은 업데이트를 기다리지 않고 삭제하는 즉시 지운다.","다만 만료 기한이 지난 문서는 업데이트 없이 그 시각부터 검색 결과에서 빠진다.","만료 기한을 지난 시각으로 고치면 그 즉시 검색에서 빠진다.","지식베이스에 연결한 데이터 관리 파일은 이름 변경, 이동, 삭제가 막힌다.","내 PC 업로드는 16종 형식만 받고, 스토리지 사용률이 95% 이상이면 막는다."]},{"제목":"설정 변경과 반영 시점","문장":["임베딩 모델, 청킹 값, 그래프 추출 설정, 메타데이터 스키마를 바꾸면 반영 대기로 저장된다.","반영 대기 설정은 다음 검색 DB 생성이 끝나는 순간 적용되고, 그 전까지 검색은 직전 버전과 그 설정으로 한다.","임베딩 모델, 청킹 값, 그래프 추출 설정을 바꾸면 반영 방식은 「전체 문서로 생성」만 고를 수 있다.","리랭커, 리랭크 결과 수, 검색 결과 수, Simple 유형의 LLM 변경도 반영 대기로 저장된다.","리랭커와 검색 결과 수 변경은 색인을 건드리지 않아 「변경분 반영」 업데이트로도 반영한다.","다만 검색 DB가 아직 없으면 반영 대기 없이 바로 저장하고 첫 생성에 쓴다.","반영 대기 값을 저장 전 값으로 되돌리면 반영 대기에서 빠진다.","검색 DB 생성 중과 평가 중에는 설정 탭의 설정을 고칠 수 없다.","생성이 중지되거나 실패해도 반영 대기는 그대로 남아 다음 생성에 반영된다."]},{"제목":"검색 DB 생성과 버전 번호","문장":["[검색 DB 생성]과 [검색 DB 업데이트]는 지식베이스가 배포중일 때만 실행한다.","실행 조건은 문서 1건 이상과 필수 모델(Simple 유형은 임베딩 모델, Graph 유형은 LLM과 임베딩 모델)이다.","실행하면 상태가 실행중이 되고, 완료, 중지, 실패로 끝나면 배포중으로 돌아간다.","진행률과 세부 단계는 표시하지 않는다.","버전 번호는 완료한 생성에만 붙고, 중지와 실패는 「v7 중지」, 「v7 실패」로 남는다.","번호는 건너뛰지 않아, 중지나 실패 뒤 다시 완료하면 같은 번호로 「v7 적용」이 된다.","일부 문서만 실패하면 생성은 완료이고 새 버전을 준다.","실패한 문서는 반영 실패로 남고 다음 업데이트에서 다시 처리한다.","다만 모든 문서가 실패하면 생성 실패다.","생성이 실패하면 실행자와 관리자에게 실패 알림을 보내고 작업 이력에 실패 원인이 남는다.","생성 도중 [배포 중지]하면 생성도 함께 중지되어 「vN 중지」로 남는다.","쓰던 임베딩 모델이나 리랭커의 모델 배포가 중지되어 있으면 생성은 그 단계에서 실패한다.","생성할 때마다 청크 품질 문제를 문서별로 집계해 그 버전에 남긴다."]},{"제목":"업데이트 중 검색과 버전 전환","문장":["업데이트가 끝날 때까지 시스템은 마지막으로 완료한 버전으로 검색한다.","업데이트가 완료되는 순간 다음 질문부터 새 버전으로 검색한다.","연결한 에이전트는 다시 배포하지 않고 새 버전을 쓰며, 그 에이전트의 작업 이력에 시스템 줄이 남는다.","업데이트가 실패하거나 중지되면 마지막으로 완료한 버전으로 계속 검색한다.","이전 버전으로 되돌리는 롤백은 없고, 지난 버전은 작업 이력에 번호로만 남는다.","다만 첫 생성이 실패하거나 중지되면 쓸 버전이 없어 테스트와 평가를 할 수 없다.","완료하면 이 지식베이스를 연결한 모든 에이전트(배포 전 포함)의 생성자와 관리자에게 버전 변경을 알린다.","서비스 API에 오픈된 에이전트에 보내는 버전 변경 알림은 조치가 필요한 알림이다.","업데이트가 실패하면 연결 자원 변경 알림을 보내지 않는다."]},{"제목":"스토리지 확인과 지난 버전 정리","문장":["업데이트 전에 앞 버전 크기를 예상 용량으로 보고 잔여 스토리지보다 크면 [검색 DB 업데이트]를 막는다.","첫 생성은 앞 버전이 없어 예상 용량 검사를 하지 않는다.","스토리지 사용률이 95% 이상이면 새 생성을 막는다.","생성 도중 스토리지가 가득 차면 실패(스토리지 부족)로 끝나고, 직전 버전이 있으면 그 버전으로 검색을 계속한다.","업데이트가 완료되면 시스템은 직전 버전의 색인을 바로 지운다.","지운 버전을 쓰던 에이전트 회차로 롤백하면 현재 검색 DB 버전을 쓴다.","지운 버전이 든 에이전트 회차를 다운로드하면 넣지 못한 검색 DB를 패키지 안내 파일에 적고 다운로드는 막지 않는다."]},{"제목":"평가 중 잠금과 평가 실행","문장":["평가나 평가셋 생성 중에는 검색 DB 생성, 설정 수정, 배포 중지, 삭제를 막고, [중지]한 뒤 진행한다.","검색 DB를 만드는 동안에는 평가를 실행할 수 없다.","평가는 문항마다 지금 검색 DB 버전으로 검색해 답변을 생성하고 채점하며, 결과에 그 버전을 남긴다.","평가셋이 지금보다 이전 검색 DB 버전으로 만들어졌으면 확인을 선택해야 평가를 실행한다.","채점 모델은 서로 다른 계열로 최대 3개이고, 점수는 중앙값, 판정은 다수결이며 의견이 갈리면 판정 보류다.","중지한 평가는 결과로 남기지 않고, 중지는 권한이 필요 없다.","검색 DB 버전이 바뀌어도 이전 평가 결과는 유효하다.","이미 시작한 검색 DB 생성, 업로드, 평가는 편집 점유가 풀려도 계속된다."]},{"제목":"지식베이스 삭제","문장":["삭제는 권한을 거치지 않고 이름을 입력해 확인한다.","대기, 설치중, 배포중, 실행중이면 삭제할 수 없고 [배포 중지] 뒤 삭제한다.","검색 DB 생성 중, 평가 중, 배포된 에이전트가 연결함, 승인 대기 요청, 다른 구성원 편집 중이면 삭제를 막는다.","삭제하면 내 PC에서 올린 문서, 검색 DB의 모든 버전, 검색 컨테이너, 평가 결과를 함께 지운다.","데이터 관리에서 고른 문서와 평가셋 파일은 데이터 관리에 남는다.","다만 내 PC에서 올린 문서를 다른 작업이 쓰면 그 파일은 지우지 않는다.","다만 배포 전 에이전트가 연결했으면 삭제를 막지 않고, 그 에이전트에 「삭제됨」 참조를 남긴다."]},{"제목":"검색 한도와 실패 집계","문장":["에이전트가 연결한 지식베이스에 서비스 사용자의 접근 권한이 없거나 한도를 넘으면 그 지식베이스만 빼고 요청을 이어 간다.","제외한 지식베이스는 응답에 알리고, 권한이나 한도로 뺀 것은 노드 실패가 아니다.","서비스 사용자의 접근 권한과 사용자별 한도는 권한 설정이 정한다.","전체 일일 요청 상한은 모든 서비스 사용자의 검색 요청 합계이고, 빈 값은 제한 없음이다.","전체 일일 요청 상한은 매일 0시부터 하루 단위로 세고 0시에 셈을 처음부터 다시 한다.","상한을 넘은 검색은 막고 기록한다.","검색 테스트는 전체 일일 요청 상한에 세지 않는다.","모니터링은 성공과 결과 없음을 정상, 권한 거부와 한도 초과를 경고, 시간 초과와 검색 실패만 에러로 센다.","검색이 시간 초과나 검색 실패로 끝나면 그 노드는 에이전트 실행의 노드 실패 규칙을 따른다.","쓰던 임베딩 모델 배포가 중지되면 그 모델이 다시 배포될 때까지 검색은 실패로 센다.","배포중이 아니면 지표를 수집하지 않고, 배포를 중지해도 지난 기간의 지표는 남는다."]}]},{"주제":"도구·MCP","개요":"에이전트 노드가 외부 시스템을 부르는 도구의 배포, 개인 인증, 동작 목록 갱신, 설정 반영 시점, 호출 실패와 한도 집계를 다룬다.","묶음":[{"제목":"도구 배포와 호출 대상","문장":["도구는 시스템이 두는 제공 도구와, 외부 REST API나 MCP 서버로 만드는 Custom 도구가 있다.","생성한 도구는 자원을 잡지 않고, [배포]로 도구 컨테이너를 띄운 뒤 자원을 점유한다.","제공 도구도 [배포]해야 호출된다.","에이전트 노드는 배포중인 도구의 선택한 동작만 고르고 호출한다.","선택한 동작이 없는 도구는 [배포]를 막는다.","다만 동작이 아직 없는 MCP 서버 도구는 [배포]를 막지 않고 배포할 때 동작 목록을 받는다.","[배포]와 오토 스케일링에서 자원을 늘리는 조작만 컴퓨팅 자원 사용 권한을 거친다.","자원 대기, 예약, 반복 예약 규칙은 지식베이스 배포와 같다.","[배포 중지]는 권한과 관계없이 확인 뒤 바로 중지하고 실행 자원을 반환한다.","배포중인 에이전트가 쓰거나 다른 구성원이 편집 중이면 [배포 중지]를 막는다.","중지한 도구를 쓰던 배포 전 에이전트는 테스트에서 그 도구를 부를 수 없다.","자원 회수로 도구 컨테이너가 내려가면 대기로 돌아가고 자원이 반환되면 자동으로 다시 배포한다."]},{"제목":"개인 인증","문장":["도구는 공용 인증 값을 저장하지 않는다.","외부 REST API 도구는 인증 방식만, MCP 서버 도구는 인증 항목(환경 변수 이름)만 정한다.","인증 값은 에이전트 테스트와 서비스에서 도구를 부르는 사용자가 그때마다 개인 인증으로 넣는다.","인증 방식이 「인증 없음」인 도구는 개인 인증 없이 호출한다.","서비스 사용자의 개인 인증이 없는 도구가 호출되면 그 도구만 빼고 요청을 이어 가고, 응답에 인증 필요 안내를 담는다.","개인 인증이 없어 뺀 도구는 노드 실패가 아니다.","도구에는 연결 상태와 인증 만료가 없어, 모니터링과 작업 이력에 인증 상태를 표시하지 않는다.","인증 문제는 호출마다 「외부 인증 실패」로만 남는다.","에이전트 테스트에서는 테스트하는 구성원의 인증 토큰을 그 테스트에만 쓰고 다운로드 패키지에 넣지 않는다."]},{"제목":"MCP 동작 목록 갱신","문장":["MCP 서버 도구는 [배포]할 때마다 서버에서 동작 목록을 다시 받는다.","새로 받은 동작은 선택하지 않은 상태로 더하고, 있던 동작의 선택 여부는 그대로 둔다.","목록에서 사라진 동작은 「서버에서 제공하지 않음」으로 바뀌고 선택이 해제된다.","다만 배포중인 에이전트가 쓰는 동작도 서버에서 사라지면 선택을 해제한다.","사라진 동작을 쓰는 에이전트의 생성자와 관리자에게 조치가 필요한 알림(도구 호출 불가)을 보낸다.","선택한 동작이 0개가 되면 도구 배포를 중지한다.","서버가 동작 목록을 주지 못하면 설치중에서 실패로 끝나고, 이전 목록은 그대로 둔다.","[연결 테스트]는 서버의 동작 목록을 미리 보여 주기만 하고 저장하지 않는다."]},{"제목":"배포 중 설정 변경의 적용 시점","문장":["동작 선택을 해제하면 즉시 적용되어, 그 순간부터 에이전트가 그 동작을 부르지 않는다.","동작을 선택하면 그 즉시 에이전트 노드에서 고를 수 있다.","엔드포인트 수정과 그 밖의 연결 설정 변경은 다음 배포 회차부터 적용되고, 지금 회차는 바꾸기 전 값으로 호출한다.","외부 REST API의 기본 주소와 인증 방식, MCP 서버의 주소나 실행 명령과 인증 항목은 생성 뒤 바꿀 수 없다.","배포중인 에이전트가 쓰는 동작은 선택 해제, 엔드포인트 수정, 엔드포인트 삭제를 막는다.","배포중인 도구에서 마지막 동작을 해제하면 권한과 관계없이 확인 뒤 배포를 중지하고 실행 자원을 반환한다.","다만 대기나 설치중인 도구에서 마지막 동작을 해제하면 대기나 설치를 끝내고 중지로 둔다.","해제한 동작을 쓰던 배포 전 에이전트의 노드는 그 동작을 「사용 안 함」으로 표시하고 생성자에게 연결 자원 변경 알림을 보낸다.","동작 선택 변경은 그 배포 회차의 작업 내역에 사용과 사용 안 함으로 남는다.","배포하지 않은 동안 바꾼 내용은 다음 배포 회차의 이전 회차 대비 변경으로 남는다."]},{"제목":"호출 실패와 다시 연결","문장":["도구 호출이 실패하면 그 호출만 실패로 처리하고, 에이전트는 노드 실패 규칙을 따른다.","시간 제한(처음 값 60초)을 넘은 호출은 시간 초과로 끝낸다.","외부 서비스가 응답하지 않으면 시스템이 1분 간격으로 3번까지 다시 연결한다.","다시 연결하는 동안 들어온 호출은 시간 초과 에러로 센다.","다시 연결되면 배포중을 유지하고, 응답 없음과 복구는 작업 이력에 시스템 줄로 남는다.","3번 모두 실패하면 도구를 실패로 바꾸고 생성자와 관리자에게 중단 알림을 보낸다.","다만 외부 서비스가 서비스 사용자의 인증을 거부하면 다시 연결하지 않는다.","인증 거부는 그 호출만 「외부 인증 실패」로 세고, 도구 상태와 다른 사용자의 호출은 그대로 둔다.","인증 거부를 받은 호출의 응답에는 인증이 필요하다는 안내를 담는다."]},{"제목":"호출 한도와 모니터링 집계","문장":["서비스 사용자의 도구 접근 권한과 사용자별 호출 한도는 권한 설정이 정한다.","전체 시간당 호출 상한은 도구 생성과 수정에서 정하고, 빈 값은 제한 없음이다.","전체 시간당 호출 상한은 매시 정각부터 한 시간 단위로 세고 정각에 셈을 처음부터 다시 한다.","한도를 넘은 호출만 거절 문장으로 돌려주고 기록하며, 요청은 계속 진행한다.","한도나 권한으로 거절한 호출은 노드 실패가 아니다.","모니터링은 권한 거부와 호출 한도 초과를 경고로 따로 센다.","모니터링은 외부 서비스의 시간 초과, 외부 인증 실패, 외부 서비스 오류만 에러로 센다.","배포중이 아니면 지표를 수집하지 않는다."]},{"제목":"도구 삭제","문장":["삭제는 권한을 거치지 않고 이름을 입력해 확인하며, 도구 컨테이너와 설정을 지워 복구할 수 없다.","대기, 설치중, 배포중이면 삭제할 수 없고 [배포 중지] 뒤 삭제한다.","배포된 에이전트가 연결함, 승인 대기 요청, 다른 구성원 편집 중이면 삭제를 막는다.","제공 도구는 삭제할 수 없고, 쓰지 않을 동작은 선택을 해제한다.","다만 배포 전 에이전트가 연결했으면 삭제를 막지 않고, 그 노드에 「삭제됨」 참조를 남긴다.","삭제한 도구를 쓰던 에이전트의 생성자와 관리자에게 「연결한 {이름}이 삭제되었습니다.」 알림을 보낸다."]}]},{"주제":"에이전트 설계·배포","개요":"모델, 지식베이스, 도구를 노드로 이어 에이전트를 설계하고, 검증, 배포, 편집 점유, 배포 중 프롬프트 반영, 보안 평가 중 잠금, 롤백을 다룬다.","묶음":[{"제목":"상태와 배포","문장":["상태는 생성됨, 설치중, 배포중, 중지, 실패 다섯이고 대기와 실행중은 없다.","에이전트 배포는 실행 자원을 점유하지 않아 권한, 자원 대기, 예약이 없다.","배포, 배포 중지, 롤백은 모든 구성원이 승인 없이 한다.","[배포]하면 배포 전 검증을 통과한 저장된 정의로 설치중이 되고, 설치가 끝나면 배포중이 된다.","배포중에 들어가는 순간 새 배포 회차가 생기고, 생성은 0회차다.","설치에 실패하면 실패 상태가 되고 회차는 생기지 않는다.","배포할 수 있는 상태는 생성됨, 중지, 실패이고, 실패한 에이전트는 모든 설정을 고칠 수 있다.","새 회차는 서비스 API 오픈을 새로 해야 서비스에서 부를 수 있다.","설치중, 배포 중지 중, 보안 평가 중에는 편집, 삭제, 롤백을 막는다."]},{"제목":"배포 전 검증","문장":["[배포]를 누르면 시스템이 노드 설정과 연결을 검증하고, 막는 항목이 하나라도 있으면 배포하지 않는다.","막는 항목은 한 번도 저장하지 않음, 노드 설정 누락, 시작에서 출력까지 경로 단절, 출력 노드 둘 이상이다.","에이전트 노드가 하나도 없으면 배포를 막는다.","에이전트 노드 수에는 에이전트, Built-in(마스킹, 가드레일, 코드 에이전트), 외부 에이전트 노드를 모두 센다.","연결 대상이 삭제됨이거나 준비되지 않았으면 배포를 막는다.","준비되지 않음은 모델 배포가 배포중이 아님, 지식베이스의 검색 DB나 실행 자원 없음, 도구 컨테이너 미실행이다.","부르는 에이전트가 배포중이 아니거나, 순환 안의 규칙·검토 노드에 최대 통과 횟수가 비어 있으면 배포를 막는다.","걸린 항목은 노드, 사유, 조치를 함께 보인다.","외부로 나가는 호출 앞에 마스킹이나 가드레일이 없으면 경고만 하고 배포는 허용한다.","검증 실패는 배포가 시작되지 않아 작업 이력에 남기지 않는다.","오케스트레이터가 구성하는 동안(마지막 조작 뒤 2분까지)은 검증 경고를 띄우지 않는다."]},{"제목":"편집 점유와 자동 저장","문장":["편집 점유는 에이전트 하나에 한 명이고, [편집]으로 편집 모드에 들어가는 순간 편집자가 된다.","다른 구성원은 조회, 메뉴 이동, 필터, 검색, 정렬, 복사만 할 수 있다.","다른 구성원에게 수정, 삭제, 배포, 배포 중지, 테스트 질문, 보안 평가 [실행]은 비활성이고 「{이름}님이 편집 중입니다.」를 보인다.","편집 점유는 [편집 완료], 화면 이탈, 접속 종료, 3분 무조작 가운데 하나로 풀린다.","편집자가 2분 30초 동안 조작하지 않으면 「30초 뒤 뷰어로 전환합니다.」를 알리고, 3분이 되면 뷰어로 바꾼다.","3분과 30초는 고정 값이고, 인계 요청과 강제 인계는 없다.","같은 에이전트 안의 탭 이동은 이탈이 아니다.","브라우저가 비정상 종료되면 접속 종료로 보고 점유를 놓으며, 판정이 늦으면 3분 무조작으로 놓인다.","캔버스는 조작할 때마다 자동 저장되어, 뷰어로 바뀌어도 고친 내용은 남는다.","자동 저장은 정의만 바꾸고 배포 상태와 회차는 바꾸지 않는다.","편집 시작과 종료, 저장하지 않은 편집은 작업 이력에 남기지 않는다.","편집 점유가 풀려도 이미 실행 중인 학습과 배포는 계속된다.","다만 배포 중 프롬프트를 고치다 무조작, 이탈, 접속 종료로 끝나면 저장만 하고 운영 회차에는 반영하지 않는다.","오케스트레이션이 실행되는 동안에는 편집자 여부와 관계없이 에이전트 화면 전체가 보기 전용이다."]},{"제목":"배포 중 수정 범위","문장":["배포중에는 프롬프트 계열만 고칠 수 있다.","프롬프트 계열은 에이전트와 외부 에이전트 노드의 프롬프트, 마스킹 추가 기준, 가드레일 점검 기준, 코드 에이전트 추가 지시다.","노드, 연결선, 모델, 지식베이스와 도구 연결, 변수, 규칙 조건, 입출력 형식은 배포 중에 바꿀 수 없다.","이것들을 바꾸려면 서비스 API 오픈을 해제하고 배포를 중지한 뒤 편집해 다시 배포한다.","다시 배포한 새 회차는 서비스에서 부르기 전에 다시 오픈해야 한다.","이름과 설명은 배포 중에도 권한 없이 바로 저장한다.","배포 중에는 규칙 조건을 고칠 수 없어 작업 이력에 규칙 조건의 반영 대기 줄이 생기지 않는다."]},{"제목":"배포 중 프롬프트 반영","문장":["배포중에 프롬프트를 고치고 [편집 완료]를 누르면 다시 배포하지 않고 지금 회차에 반영한다.","반영 뒤 시작한 요청부터 새 프롬프트를 쓴다.","이미 처리 중인 요청은 시작할 때의 프롬프트로 끝까지 처리한다.","자동 저장만으로는 운영 회차에 반영하지 않는다.","반영해도 회차는 바뀌지 않고 서비스 API 오픈은 그대로 유지된다.","반영할 때 바뀐 노드마다 현재 회차의 작업 이력에 프롬프트 변경 한 줄을 남긴다.","고쳤다가 처음 값으로 되돌린 노드는 이력을 남기지 않는다.","저장만 된 프롬프트는 다음 편집자가 [편집 완료]를 누를 때 함께 반영한다.","보안 평가를 실행하는 동안에는 프롬프트도 고칠 수 없다."]},{"제목":"프롬프트 되돌리기","문장":["작업 이력의 프롬프트 변경 줄에서 되돌리면 그 값이 지금 회차에 바로 반영되고 새 줄이 남는다.","다만 배포중이 아니면 프롬프트 되돌리기를 할 수 없다.","다만 다른 구성원이 편집 중이면 프롬프트 되돌리기를 막는다.","편집 모드의 [되돌리기]와 [다시 실행]은 직전 편집을 취소하거나 다시 적용하고, 결과도 자동 저장한다.","배포중에는 [되돌리기]가 프롬프트 변경만 되돌린다.","배포 상태가 바뀌거나 편집 모드를 다시 들어오면 되돌리기 기록은 비워진다."]},{"제목":"보안 평가 중 잠금과 중지","문장":["보안 평가를 실행하는 동안 편집, 배포, 배포 중지, 삭제, 롤백, 평가 설정 변경을 막는다.","막힌 조작에는 「보안 평가를 실행하고 있습니다. 보안 평가를 중지한 뒤 진행합니다.」를 보인다.","편집자가 평가를 중지하면 그때까지의 대화와 판정이 저장하지 않은 결과로 남고 잠금이 풀린다.","저장하지 않은 결과는 하나뿐이라 다음 실행 결과로 대체된다.","이름을 입력해 저장하면 공격에 성공한 대화로 평가셋 버전이 만들어진다.","평가가 끝나면 실행자와 관리자에게 작업 종료 알림을 보내고, 실행과 중지는 작업 이력에 한 줄씩 남는다.","다만 평가 도중 모델 배포 장애로 오류 문장이 답이 된 대화는 방어로 세지 않고 「판정 불가」로 따로 센다."]},{"제목":"배포 중지","문장":["구성원이 [배포 중지]를 확인하면 상태는 배포 중지 중이 되고, 진행 중인 대화가 끝나기를 기다린다.","대화가 끝나면 주소를 회수해 중지가 되고, 지금 배포 회차가 끝난다.","배포 중지는 권한이 필요 없고 배포 중지 요청은 없다.","서비스 API가 오픈된 동안 그 에이전트가 오픈됨이거나 해제 승인 대기이면 배포 중지를 막는다.","에이전트 오픈 요청이 승인을 기다리거나 보안 평가 중이면 배포 중지를 막는다.","배포중인 다른 에이전트가 외부 에이전트 노드로 부르고 있으면 배포 중지를 막는다.","막는 이유가 여럿이면 서비스 API 오픈, 오픈 요청 대기, 다른 에이전트 호출, 보안 평가 순으로 하나만 보인다.","다만 서비스 API 오픈이 중지 상태이면 오픈해 둔 에이전트도 중지할 수 있고, 그때 에이전트 오픈도 해제된다.","그 해제는 서비스 API 오픈의 작업 이력에 「오픈 해제(배포 중지)」로 남는다.","에이전트가 배포중인 동안 연결한 모델 배포, 지식베이스, 도구는 배포 중지와 삭제가 막힌다."]},{"제목":"회차 롤백","문장":["작업 이력 회차 상세에서 [이 회차로 롤백]하면 그 회차의 정의로 새 회차를 배포한다.","롤백한 프롬프트는 그 회차가 끝난 시점의 마지막 프롬프트다.","배포중이면 지금 회차를 먼저 중지하고, 마지막 배포 뒤 저장한 편집은 지워진다.","작업 이력에 롤백 한 줄과 바뀐 항목마다 설정 변경 줄이 남는다.","롤백은 권한이 필요 없고, 지금 회차에는 롤백을 두지 않는다.","그 회차의 지식베이스나 도구가 삭제되었으면 빼고 롤백하고, 그 노드는 호출하지 못한다고 확인 창에 보인다.","그 회차의 검색 DB 버전이나 커밋이 지워졌으면 현재 검색 DB 버전이나 현재 배포된 커밋을 부른다.","다만 그 회차의 모델 배포가 삭제되었거나 배포중이 아니면 롤백을 막는다.","다만 서비스 API에 오픈된 회차가 배포중이거나 오픈 요청이 대기 중이면 롤백을 막아, 서비스 호출이 끊기지 않는다.","다만 다른 구성원 편집 중, 설치중, 배포 중지 중, 다른 에이전트 호출 중, 보안 평가 중이면 롤백을 막는다.","새 회차 배포가 실패하면 이전 회차로 자동으로 돌아가지 않고 실패 상태로 남으며 실행자에게 실패 알림을 보낸다.","실패 뒤에는 다시 [배포]하거나 다른 회차로 롤백한다.","롤백으로 생긴 새 회차는 서비스 API 오픈을 새로 해야 한다."]},{"제목":"사용자 검토 노드와 서비스 응답","문장":["실행이 사용자 검토 노드에 닿으면 멈추고 검토자에게 안내 메시지와 분기를 보인다.","기본 분기는 승인, 거부, 직접 입력이고 셋 다 지울 수 없으며, 직접 입력은 검토자가 쓴 글을 그대로 넘긴다.","서비스 API로 부른 요청은 검토자가 서비스 사용자이다.","서비스 API 요청이 검토 노드에서 멈추면 응답으로 검토 대기 상태와 선택지를 돌려준다.","서비스가 재개 호출로 분기를 보내면 그 분기로 실행을 이어 간다."]},{"제목":"작업 이력과 회차 다운로드","문장":["작업 이력은 지우지 않고, 시스템 설정의 이력 표시 기간은 화면에 보이는 기간만 정한다.","리포트, 롤백, 회차 다운로드는 표시 기간과 관계없이 모든 기록과 회차를 쓴다.","작업 이력 목록은 최근 10회차(관리자가 3~50회차로 바꿈)를 보이고, 더 오래된 회차는 리포트에서 본다.","연결 대상의 새 버전처럼 시스템이 바꾼 일은 실행자 없는 시스템 줄로 남는다.","회차 다운로드는 정의, 연결 자원, 실행 구성, 그 회차의 커밋, 이 에이전트의 보안 평가셋 전부를 담는다.","비밀값, 계정과 권한, 호출 이력, 모니터링, 테스트 대화, 컨테이너 이미지, 노드 풀과 GPU 할당은 넣지 않는다.","다운로드 권한이 없으면 요청하고, 승인은 요청한 회차에 묶여 1회 다운로드나 7일 경과 가운데 먼저 오는 때 끝난다.","커밋이나 검색 DB가 지워졌으면 넣지 못한 파일을 패키지 안내 파일에 적고 다운로드는 막지 않는다."]}]},{"주제":"에이전트 실행","개요":"배포한 에이전트가 요청을 처리할 때의 노드 실패, 차단, 검토 대기, 프롬프트 반영 예외, 저장된 응답, 연결 자원 변경, 모니터링 집계를 다룬다.","묶음":[{"제목":"노드 실패와 요청 종료","문장":["실행 중 노드 하나가 실패하면 요청 전체를 끝내고 실패 응답을 돌려준다.","실패 응답과 호출 이력에는 실패한 노드 이름을 남긴다.","노드마다 실패 분기와 재시도 설정은 없고, 재시도와 대체 경로는 규칙 노드로 설계한다.","연결 대상이 실패하거나 지워진 뒤 들어온 요청에서 그 노드는 노드 실패로 처리한다.","다만 권한이 없거나 한도를 넘어 뺀 지식베이스와 도구, 개인 인증이 없어 뺀 도구는 노드 실패가 아니다.","뺀 지식베이스와 도구는 빠진 이유와 함께 실행 내역과 응답에 남는다.","규칙 노드나 사용자 검토 노드의 최대 통과 횟수를 넘으면 그 자리에서 실행을 끝낸다.","노드별 처리 집계에는 차단과 통과 횟수 초과로 끝난 요청도 그 노드의 처리로 센다."]},{"제목":"마스킹과 가드레일 차단","문장":["실행을 멈추는 조치는 차단뿐이다.","마스킹의 알림 조치는 탐지 사실을 남기고 원문을 넘기며, 마스킹 조치는 탐지 구간을 바꿔 넘긴다.","가드레일의 수정 조치는 고친 답을, 알림 조치는 원답을 넘긴다.","조치가 차단인 노드의 차단 포트에 노드가 이어져 있으면 차단된 요청은 그 경로로 간다.","차단 포트를 잇지 않았으면 차단된 요청은 그 자리에서 실행을 끝낸다.","차단으로 끝난 요청의 결과는 「차단」이고 에러로 세지 않는다.","판정 답이 최대 토큰에서 끊기고 이어 쓰기가 꺼져 있으면 탐지 실패로 본다.","탐지 실패는 조치가 알림이면 원문을 넘기고, 차단이면 차단 포트를 따르며, 그 밖의 조치는 실행을 끝낸다.","마스킹과 가드레일의 판정 모델 사용량도 크레딧과 실행 내역에 넣는다."]},{"제목":"검토 대기와 재개 호출","문장":["서비스 API 호출이 검토 노드에서 멈추면 시스템은 재개 호출을 7일 기다린다.","기다리는 동안 그 요청은 검토 대기로 남는다.","7일 안에 재개 호출이 없으면 실행을 끝내고 결과를 「검토 시간 초과」로 남긴다.","검토 시간 초과는 에러로 세지 않는다.","검토를 기다린 시간은 응답 시간에 넣지 않는다.","7일이 지난 뒤 온 재개 호출에는 「검토 대기 시간이 지나 실행을 끝냈습니다.」를 돌려준다.","다만 검토를 기다리는 동안 서비스 API 오픈을 중지하거나 에이전트 배포를 중지하면 그 실행을 끝낸다."]},{"제목":"배포 중 프롬프트 반영 예외","문장":["기본은 [편집 완료]를 누른 다음 요청부터 바뀐 프롬프트를 적용하는 것이다.","다만 [편집 완료] 순간 배포가 점검 중이면 저장만 하고 반영을 건너뛴다.","반영을 건너뛰면 진행 중인 요청과 다음 요청은 바꾸기 전 프롬프트로 처리한다.","반영을 건너뛰면 편집자에게 반영하지 못했다고 알리고 작업 이력 줄을 「반영 대기」로 남긴다.","점검이 끝난 뒤 [편집 완료]를 다시 누르면 그때 반영한다.","다만 오래전에 띄운 배포는 반영을 거절하고 「배포를 중지했다가 다시 배포하세요」를 보인다.","다시 배포하면 새 회차가 열리고 그 뒤로는 [편집 완료] 순간 바로 반영된다.","서비스 API에 오픈된 에이전트는 오픈을 먼저 해제해야 배포를 중지할 수 있다.","다만 편집자가 3분 동안 조작하지 않아 뷰어로 바뀌면 저장만 하고 반영하지 않는다."]},{"제목":"저장된 응답과 프롬프트 변경","문장":["응답 캐시는 같은 질문에 저장해 둔 답을 다시 돌려주는 설정이고 처음 값은 사용 안 함이다.","응답 캐시는 서비스 API 오픈의 응답 캐시도 사용일 때만 실제로 적용한다.","배포 중 프롬프트를 반영하는 순간 그 에이전트에 저장된 응답을 모두 지운다.","저장된 응답을 지운 뒤 다음 요청부터 바뀐 프롬프트로 만든 답이 나간다.","프롬프트 반영으로 지운 응답의 삭제 사유는 「프롬프트 변경」으로 기록한다.","다만 반영을 건너뛰면 저장된 응답도 지우지 않는다.","저장된 응답으로 돌려준 호출은 호출 이력에 결과 「캐시 응답」으로 남는다."]},{"제목":"연결 자원 변경의 반영","문장":["연결한 지식베이스, 도구, 모델 배포가 바뀌면 에이전트는 다시 배포하지 않고 바뀌는 순간부터 바뀐 것을 쓴다.","지식베이스는 검색 DB 업데이트가 끝나는 순간부터 새 버전으로 검색한다.","모델 배포는 롤링 업데이트 교체가 끝난 뒤의 호출부터 새 버전을 부른다.","도구 동작을 사용 안 함으로 바꾸면 그 순간부터 그 동작을 부르지 않는다.","에이전트의 회차는 그대로이고, 작업 이력에 시스템 줄과 상세 정보에 변경 내용이 남는다.","에이전트 생성자와 관리자에게 연결 자원 변경 알림을 보내고, 서비스 API에 오픈된 에이전트는 조치가 필요한 알림이다.","다만 연결한 대상이 실패하거나 지워지면 그 노드는 노드 실패로 처리되어 요청이 끝난다.","배포중인 동안 연결 대상이 내려가면 에이전트는 배포중으로 남고, 상세에 그 노드를 지나는 요청이 실패한다고 알린다.","실행할 때는 요청한 사용자의 권한으로 쓸 수 있는 지식베이스와 도구만 쓴다."]},{"제목":"모니터링 집계","문장":["호출은 요청이 끝난 뒤에 세고, 진행 중인 요청은 끝나야 들어간다.","호출 지표는 1분 단위로 모은다.","화면은 다시 열거나 기간을 바꿀 때 최신 값을 읽는다.","서비스 API로 들어온 요청은 서비스 호출로 센다.","채팅 테스트와 보안 평가는 AGENTBASE 호출의 「에이전트 테스트」와 「보안 평가」로 센다.","AGENTBASE 호출은 서비스 사용자의 사용량과 한도에 넣지 않는다.","테스트 질문의 크레딧은 크레딧 비율로 계산해 보이기만 한다.","배포가 멈췄거나 응답하지 않은 서비스 호출은 에러로 센다.","삭제된 서비스 사용자의 요청은 차단으로 세어 에러율에 넣지 않는다.","배포 전에는 호출이 없어 지표가 비어 있다.","만족도는 서비스가 보낸 좋아요와 싫어요를 실행 식별자로 원래 요청에 붙여 계산하고, 없는 식별자는 넣지 않는다."]}]},{"주제":"에이전트 보안 평가","개요":"배포한 에이전트에 공격 대화를 보내 방어율을 재는 동작과, 서비스 API 오픈 및 프롬프트 변경과의 관계를 다룬다.","묶음":[{"제목":"서비스 API 오픈과의 관계","문장":["보안 평가는 서비스 API 오픈의 필수 조건이 아니어서, 평가하지 않은 에이전트도 오픈할 수 있다.","보안 평가에는 통과 기준이 없고, 시스템은 방어율을 기준값과 비교하지 않는다.","새 회차에 보안 평가 결과가 없어도 서비스 API 오픈을 막지 않는다.","오픈 창과 승인 창에는 지금 회차에서 끝나고 저장한 결과의 방어율을 참고값으로 보인다.","편집자가 표시 결과로 고른 결과가 지금 회차에서 저장한 결과이면 그 방어율을 참고값으로 쓴다.","다만 지금 회차에서 저장한 결과가 모두 지워지면 방어율 참고값은 「-」다.","저장한 결과는 서비스 API 오픈 상태와 관계없이 지울 수 있고, 지워도 오픈은 그대로다."]},{"제목":"프롬프트 변경과 결과 유효성","문장":["배포 중 프롬프트 변경은 회차를 바꾸지 않으므로 그 회차의 보안 평가 결과는 그대로 유효하다.","프롬프트를 바꾼 뒤에도 방어율 참고값은 같은 회차에서 저장한 결과로 계속 보인다.","다시 배포나 롤백으로 새 회차가 열리면 참고값은 새 회차에서 끝나고 저장한 결과만 쓴다."]},{"제목":"평가 설정","문장":["평가 모드는 신규 평가, 평가셋 선택, 평가셋 업로드 셋이다.","신규 평가는 공격 모델, 목표, 전략, 횟수, 판정 모델을 받고 평가셋 모드는 평가셋과 판정 모델을 받는다.","횟수는 시도 1~5회(처음 1회), 대화 턴 1~10턴(처음 5턴), 강화 0~3단계(처음 1단계)이고 신규 평가에만 있다.","시스템은 설정으로 예상 요청 수를 계산해 보인다.","판정 모델은 하나 이상 고르고, 둘 이상이면 모든 모델이 공격 성공으로 판정한 경우만 공격 성공이다.","공격 모델과 판정 모델이 같은 모델 배포이면 경고만 하고 막지 않는다.","설정은 에이전트마다 저장하고, 평가가 실행되는 동안에는 바꿀 수 없다.","업로드 평가셋은 공격 대화 2,000개까지 받고, 목표, 카테고리, 공격 턴 열이 있어야 한다."]},{"제목":"평가 실행 조건과 진행","문장":["[실행]은 배포중, 편집 모드 아님, 워크스페이스의 다른 보안 평가 없음일 때만 열린다.","모드별 입력이 채워지고 판정 모델이 1개 이상이며 예상 요청 수가 20,000회 이하여야 [실행]이 열린다.","조건이 여럿 걸리면 먼저 걸린 이유 하나만 보인다.","다른 구성원이 편집 중이면 [실행]은 비활성이다.","신규 평가는 목표마다 시도 횟수만큼 전략을 골라 대화하고, 실패하면 강화 단계 수만큼 다시 시도한다.","평가셋 모드는 저장된 공격 대화를 그대로 다시 보낸다.","판정 모델은 대화가 끝난 뒤 대화 전체를 보고 공격 성공 여부를 한 번 판정한다.","평가 호출은 모니터링에서 AGENTBASE 호출의 「보안 평가」로 세고 서비스 사용자 사용량에 넣지 않는다."]},{"제목":"판정과 방어율 계산","문장":["방어율은 공격에 실패한 목표 수를 전체 목표 수로 나눈 값이다.","목표는 시도 가운데 한 번이라도 성공하면 공격 성공이다.","공격 성공에는 심각도와 성공한 턴 번호를, 공격 실패에는 근접도(1~10)를 남긴다.","근접도 7 이상은 공격에 실패했어도 점검 대상으로 표시한다.","모델 배포 장애로 오류 문장이 답이 된 목표는 「판정 불가」로 따로 세고 방어율의 분자와 분모에서 뺀다.","다만 모든 목표가 판정 불가이면 방어율은 「-」다.","결과 비교는 같은 모드, 같은 목표나 같은 평가셋, 같은 판정 모델로 측정한 결과끼리만 한다.","중지한 결과는 저장하기 전까지 방어율 참고값에 들어가지 않는다."]},{"제목":"결과 저장과 평가셋","문장":["끝난 결과에 이름을 넣어 저장하면 공격에 성공한 대화로 평가셋 버전을 만든다.","공격 성공이 없으면 결과만 저장하고 평가셋은 만들지 않는다.","같은 이름이면 결과와 업로드를 가리지 않고 생성 차례로 다음 버전(vN)을 붙인다.","평가셋은 데이터 관리의 그 에이전트 evaluations 폴더에 「이름_v버전.jsonl」 형식으로 저장한다.","실행 중인 결과는 수정, 삭제할 수 없다.","결과 저장, 수정, 삭제와 평가셋 업로드는 작업 이력에 각각 한 줄을 남긴다.","평가셋 다운로드는 다운로드 권한을 거치고, 권한이 없으면 요청 뒤 승인되면 요청자가 1회 받는다.","다른 에이전트의 평가셋도 골라 실행할 수 있지만 삭제할 수는 없다.","Built-in 목표와 전략은 고치거나 지울 수 없고, 공용 등록 요청은 관리자가 승인한 뒤 공용이 된다."]}]},{"주제":"오케스트레이터","개요":"구성원이 글로 요청한 작업을 오케스트레이터가 입력자의 권한으로 설계, 확인, 실행하는 범위와 권한 판정, 편집 점유, 중지, 기록을 다룬다.","묶음":[{"제목":"연결과 사용 가능 여부","문장":["오케스트레이터 연결은 GPUBASE에서 AGENTBASE를 만들 때 정하고 AGENTBASE 화면에서는 바꾸지 않는다.","연결되지 않으면 오케스트레이터 대화 패널과 여는 버튼을 두지 않는다.","연결되지 않으면 홈에도 입력창을 두지 않는다.","오케스트레이터가 없어도 다른 기능은 그대로 쓴다.","다만 대화를 열어 둔 채 연결이 끊기면 패널을 걷고, 지난 세션 기록은 그대로 볼 수 있다."]},{"제목":"맡기는 일과 대신하지 않는 일","문장":["새로 만들 수 있는 것은 에이전트, 지식베이스, 데이터 파이프라인, 모델 배포, 도구다.","고칠 수 있는 기존 작업은 열린 에이전트 수정과 데이터 파이프라인 모듈 삽입뿐이다.","에이전트는 생성(노드 추가, 설정, 연결, 검증), 수정, 배포를 맡는다.","모델 배포는 생성과 배포를, 지식베이스는 생성, 문서 연결, 배포, 검색 DB 생성을 맡는다.","데이터 파이프라인은 생성과 고른 노드 뒤 모듈 삽입만 하고 배포와 실행은 하지 않는다.","도구는 등록만 하고 배포하지 않으며, 동작 목록은 도구 상세에서 연결을 확인한 뒤 보인다.","배포 중지는 권한과 관계없이 입력자의 확인을 받은 뒤 대신 실행하고, 배포 중지 요청은 만들지 않는다.","학습 중지는 입력자에게 컴퓨팅 자원 사용 권한이 없으면 학습 중지 요청을 만든다.","다만 다른 구성원이 편집 중이거나 대상이 설치중이면 배포 중지를 대신하지 않고 화면과 같은 이유로 답한다.","삭제, 다운로드, 서비스 API 오픈, 리더보드 등록은 대신하지 않는다.","대신하지 않는 일은 그 일을 하는 화면과 입력자 권한에 따른 결과(바로 실행 또는 요청)를 답한다.","생성이 끝나면 만든 항목의 링크를 결과와 함께 주고, 요청을 보낸 경우에는 요청 화면으로 이동할지 묻는다."]},{"제목":"요청 해석과 실행 전 확인","문장":["요청을 받으면 해석하는 생각 과정을 먼저 보이고, 의도를 생성, 수정, 배포, 배포 중지, 안내로 나눈다.","실행할 단계 목록인 업무 설계를 보이고 진행 여부(Yes, No)를 묻는다.","단계마다 필요한 권한과 입력자의 권한 유무를 함께 적는다.","권한이 없으면 마지막 단계가 「배포 요청」으로 바뀌고 질문은 「~을 생성하고 배포 요청을 보낼까요?」가 된다.","No를 고르면 바꿀 내용을 받아 설계를 고치고 다시 확인받는다.","Yes를 고른 뒤에만 실행한다.","모델 배포 설계는 생성, 배포(또는 배포 요청) 순이다.","지식베이스 설계는 생성, 문서 연결, 배포와 검색 DB 생성(또는 배포 요청) 순이다.","에이전트 설계는 생성 또는 수정, 노드 구성과 연결과 검증, 배포 여부 확인 뒤 배포 순이다."]},{"제목":"권한 판정과 배포 요청","문장":["오케스트레이터는 대화하는 구성원(입력자)의 권한으로 움직이고, 관리자는 모든 권한이 있다.","권한은 실행 계획을 보일 때와 Yes 뒤 실행하는 순간에 두 번 보고, 둘이 다르면 실행하는 순간을 따른다.","계획을 보인 뒤 권한이 사라지면 그 단계는 실행하는 순간 요청으로 바뀐다.","권한이 필요 없는 일(에이전트 생성·수정·배포, 모델 배포와 지식베이스 생성, 문서 연결, 도구 등록, 모듈 삽입)은 끝까지 실행한다.","에이전트 배포는 실행 자원을 잡지 않아 권한과 관계없이 배포한다.","모델 배포의 배포와 지식베이스 배포, 검색 DB 생성은 컴퓨팅 자원 사용 권한이 있으면 실행한다.","권한이 없으면 만들기까지 하고 배포 요청을 보낸 데서 멈춘다.","요청 메모에는 요청 대상, 요청 값, 오케스트레이터에 요청한 내용이 담기고, 입력자가 메모를 더 적을 수 있다.","관리자가 승인하면 요청한 값으로 바로 배포하고, 지식베이스는 검색 DB 생성까지 이어서 한다.","관리자가 거절하면 만든 작업은 생성됨 상태로 남는다.","권한이 없어 요청한 모델 배포는 대기 상태(사유 승인 대기)이고, 지식베이스는 생성됨 상태로 남는다.","권한이 있어도 노드 풀의 잔여 GPU가 모자라면 모델 배포는 대기 상태로 만든다.","결과는 「컴퓨팅 자원 사용 권한이 없어 배포 요청을 보냈습니다. 관리자가 승인하면 배포합니다.」 취지로 답한다.","대화 영역이 닫혀 있으면 「요청한 오케스트레이션 작업이 종료되었습니다.」로 작업 알림을 보낸다.","보낸 배포 요청은 오케스트레이션을 중지해도 취소되지 않고 요청 관리에서 취소한다."]},{"제목":"편집 점유와 배포 상태 확인","문장":["다른 구성원이 편집 중인 작업은 수정, 노드 추가, 배포, 모듈 삽입을 하지 않는다.","그때는 「{이름}님이 편집 중이라 수정할 수 없습니다. 편집이 끝난 뒤 다시 요청합니다.」로 답한다.","편집 점유는 계획을 보일 때와 실행하는 순간에 두 번 확인한다.","배포하는 순간 다른 구성원이 편집 중이면 배포하지 않고 「{이름}님이 편집 중이라 배포할 수 없습니다.」 취지로 답한다.","열린 에이전트를 고칠 때는 편집 점유를 먼저, 배포 상태를 다음으로 확인한다.","다만 배포중(설치중, 배포 중지 중 포함)인 에이전트는 편집 점유와 별개로 계획 단계에서 막는다.","그때는 「배포 중인 에이전트에서는 프롬프트만 수정 가능합니다. 배포를 중지한 뒤 수정합니다.」로 답한다.","배포에 실패한 에이전트는 고칠 수 있다.","지식베이스를 만들 때 편집 중인 문서는 연결에서 빼고 「제외한 문서」에 편집자를 적는다.","데이터 파이프라인 모듈 삽입은 후보를 보일 때와 [적용] 순간 모두 편집 점유를 확인한다.","조회나 실패 원인 답변 같은 읽기는 편집 점유를 보지 않고 그대로 한다.","오케스트레이터가 새로 만든 작업은 입력자가 생성자이자 편집자다."]},{"제목":"실행 중 화면과 중지, 실패","문장":["실행하는 동안 AGENTBASE 전체가 보기 전용이고, 조회와 화면 이동만 허용한다.","보기 전용은 다른 구성원의 화면에도 적용한다.","다만 실행 전에 이미 시작된 학습, 배포, 업로드는 계속된다.","실행 중에는 단계별 진행 상태를 보이고, 각 작업의 결과는 끝나는 순간 목록, 상세, 작업 이력에 반영한다.","실행 중에는 새 요청을 보내거나 세션을 초기화할 수 없다.","구성원이 [중지]하면 끝난 작업은 남기고 시작한 배포는 취소한 뒤, 끝난 작업과 취소한 작업을 답한다.","중지하면 보기 전용이 풀린다.","작업 일부가 실패하면 그 자리에서 실패로 끝내고, 이미 끝난 단계는 되돌리지 않는다.","실패 뒤에는 입력창이 다시 열리고, 구성원이 다시 요청해 이어 간다.","실행 중에 화면을 새로 고치면 대화는 남기고 진행 중이던 작업은 실패가 아닌 중지로 표시한다.","새로 고침으로 중지되면 보기 전용과 실행 중 표시가 풀린다.","대화를 닫아도 진행 중인 실행은 계속되고, 끝나면 요청자 본인에게만 작업 종료 알림을 보낸다.","같은 이름의 에이전트가 있어 생성이 실패하면 목록을 확인하고 새 이름으로 다시 만든다."]},{"제목":"대화 기록과 작업 이력","문장":["대화는 세션 단위로 남고 세션은 구성원마다 따로다.","홈에서 시작한 대화는 다른 메뉴로 옮겨도 이어지고, 새로 고쳐도 남는다.","세션을 초기화하면 지금 대화는 대화 기록의 지난 세션으로 넘어가고 빈 세션이 열린다.","세션 초기화는 이미 만든 작업과 보낸 요청에 영향을 주지 않는다.","지난 세션은 읽기 전용이고, 보는 동안에는 요청을 보낼 수 없다.","대화 기록 다운로드는 다운로드 권한을 거치고, 권한이 없으면 요청 뒤 승인되면 요청자가 1회 받는다.","다운로드 승인은 1회 다운로드나 7일 경과 가운데 먼저 오는 때 끝나고, 다운로드는 감사 이력에 남는다.","오케스트레이터가 한 작업은 각 작업의 작업 이력에 실행자가 입력자로 남고 「오케스트레이터」 경유가 표시된다."]}]},{"주제":"서비스 연결·동기화","개요":"외부 서비스 하나를 두 API 로 연결하는 확인 절차와, 서비스의 권한 체계와 서비스 사용자를 가져와 반영하는 시점, 범위, 실패 처리를 다룬다.","묶음":[{"제목":"서비스 연결과 연결 확인","문장":["AGENTBASE 하나는 서비스 하나에 API 를 제공하고, 서비스 하나는 서비스 쪽과 사용자·권한 쪽 두 연결을 갖는다.","서비스 쪽은 서비스 URL 과 연결 키로, 사용자·권한 쪽은 사용자·권한 API URL 과 연결 키로 연결한다.","구성원이 연결 정보를 넣고 [저장]하면 시스템은 그 순간 서비스에 접속해 연결을 확인하고, 확인이 끝나야 저장한다.","연결을 확인하는 동안 [저장]은 「확인 중」이 되고 입력 칸은 잠긴다.","주소에 접속하지 못하면 「주소에 접속할 수 없습니다.」를 보이고 저장하지 않는다.","연결 키가 틀리거나 만료되었으면 「연결 키가 맞지 않거나 만료되었습니다.」를 보이고 저장하지 않는다.","두 연결은 서비스 ID 가 같아야 하며, 나중에 연결하는 쪽의 서비스 ID 가 먼저 연결한 쪽과 다르면 저장을 막는다.","두 쪽을 한 번에 바꾸면 서비스 쪽 응답의 서비스 ID 를 기준으로 사용자·권한 쪽을 검사한다.","서비스 쪽을 처음 연결해 저장하면 서비스 API 오픈의 0회차(오픈 준비)가 생긴다.","사용자·권한 쪽을 저장하면 그 즉시 동기화를 시작한다.","연결 키는 첫 연결에서 필수이고, 저장된 키는 가려 보이며 새 키를 넣고 저장할 때만 바뀐다.","연결을 저장하면 서비스 쪽은 「설정 변경」, 사용자·권한 쪽은 「사용자·권한 API 연결 변경」 한 줄을 작업 이력에 남긴다.","서비스 쪽 연결은 서비스 API 오픈 권한, 사용자·권한 쪽 연결은 권한 설정 변경 권한이 있어야 바로 저장할 수 있다.","다만 권한이 없는 구성원은 [연결 요청]을 보내고, 관리자가 승인하는 순간 서비스 ID 를 확인한 뒤 저장하고 동기화한다.","서비스 쪽 연결 요청과 사용자·권한 쪽 연결 요청은 따로 한 건씩 승인을 기다린다.","다만 다른 구성원의 연결 요청이 승인을 기다리는 동안에는 그 쪽 연결 창이 잠긴다.","다만 동기화가 진행되는 동안에는 사용자·권한 쪽 연결을 바꿀 수 없다."]},{"제목":"동기화 시작 시점","문장":["동기화는 관리자가 [동기화]를 눌렀을 때만 시작한다. 정해진 주기로 하는 자동 동기화는 없다.","권한 설정 변경 권한이 있는 구성원이 [동기화]를 누르면 동기화를 시작한다.","사용자·권한 API URL 을 처음 저장하거나 그 변경 요청이 승인되면 동기화를 시작한다.","다만 5분 안에 다시 알려 온 변경은 5분이 지난 뒤 한 번 더 가져와 마지막 변경까지 반영한다.","권한 설정 변경 권한이 없는 구성원에게 [동기화]는 비활성이고, 동기화 요청은 없다.","다른 구성원이 권한 설정을 편집 중이면 [동기화]는 비활성이고 「{이름}님이 편집 중입니다.」를 보인다."]},{"제목":"동기화 진행과 반영 시점","문장":["동기화는 알려 온 내용과 상관없이 연결 확인, 권한 유형과 항목, 서비스 사용자 차례로 전체를 받는다.","서비스 사용자 정보에는 계정, 이름, 속성, 크레딧 한도, 추가 지급이 들어 있다.","시스템은 전체를 끝까지 받은 뒤 한 번에 바꾸고, 받는 도중에는 기존 값을 바꾸지 않는다.","다만 사용자 한 명의 추가나 삭제만 알려 온 경우에는 전체를 받지 않고 그 사용자만 바로 반영한다.","동기화가 진행되는 동안 권한 설정은 누가 열어도 「동기화 중입니다.」와 「{이름}님이 {일시}에 시작했습니다.」로 덮인다.","동기화가 진행되는 동안 권한 값 변경, 연결 변경, [동기화]는 막히고 탭 이동만 된다.","동기화가 끝나면 덮개를 걷고 「동기화를 마쳤습니다.」를 보이며 작업 이력에 「동기화」 한 줄을 남긴다.","서비스 사용자의 요청은 동기화 중에도 멈추지 않고, 동기화 직전 값으로 권한을 판정한다.","동기화가 끝난 뒤 들어온 요청부터 새 권한 체계, 사용자, 크레딧 한도로 판정한다."]},{"제목":"동기화로 바뀌는 값","문장":["동기화는 받은 값으로 권한 체계와 사용자를 통째로 바꾸고, 바뀌기 전 값은 작업 이력의 「동기화」 줄에만 남는다.","권한 체계는 서비스가 만들고 고치며, AGENTBASE 는 받은 권한 체계를 보기 전용으로 둔다.","새로 생긴 부서·직급은 값을 지정하지 않은 권한으로 트리에 더해지고 상위 권한의 값을 받는다.","없어진 권한은 그 권한에 지정한 값과 함께 지우고, 「동기화」 줄에 지운 지정 값의 수를 적는다.","없어진 권한에 속했던 사용자는 바뀐 속성에 맞는 권한을 받고, 맞는 권한이 없으면 「전체」의 값을 받는다.","부서가 바뀐 사용자는 동기화가 끝난 뒤 들어온 요청부터 새 권한으로 판정한다.","서비스에서 삭제된 사용자는 서비스 사용자 목록에 「삭제됨」으로 남고, 그 사용자의 요청은 막힌다.","삭제된 사용자의 개인 지식베이스와 개인 도구는 정리 대상이 되어 지워진다.","삭제된 사용자의 지난 사용량과 크레딧 기록은 서비스 사용 현황에 그대로 남는다.","다만 동기화 전에 고치던 저장 전 권한 값은 동기화가 끝난 뒤 이어서 저장할 수 있다.","다만 없어진 권한에 고친 값은 버리고 「없어진 권한의 변경 n건은 반영하지 않았습니다.」를 보인다.","다만 승인을 기다리던 변경 요청의 대상 권한이 없어지면, 승인할 때 남은 칸만 적용한다."]},{"제목":"동기화 실패와 연결 끊김","문장":["일부만 받고 연결이 끊기거나 연결 키가 만료·거절되면 받은 값을 하나도 반영하지 않는다.","동기화가 실패하면 직전 권한 체계, 사용자, 크레딧 한도를 그대로 쓰고 서비스 사용자의 요청에는 변화가 없다.","동기화가 실패하면 권한 설정에 「동기화하지 못했습니다.」와 이유를 보이고, 「동기화」 줄의 반영 상태는 「실패」이다.","동기화 실패는 서비스 모니터링과 호출 이력에 영향이 없고 시스템 로그에만 남는다.","운영 중 서비스 연결이 끊기면 마지막으로 동기화한 사용자와 권한으로 호출 판정과 서비스 API 오픈을 이어 간다.","연결이 끊긴 동안에도 권한 값 저장은 되고, 저장한 값은 다음 요청부터 적용된다.","연결이 끊긴 동안 서비스에서 바꾼 값은 들어오지 않고, 다시 연결된 뒤 다음 동기화 때 한꺼번에 반영된다.","에이전트 개발, 테스트, 보안 평가는 서비스 연결 상태와 관계없이 동작한다."]},{"제목":"권한 체계에 없는 속성 값 처리","문장":["요청에 권한 체계에 없는 부서·직급 값이 오면 요청을 거부하지 않고 「전체」의 값만으로 처리한다.","이 요청은 「전체」가 허용하지 않은 지식베이스와 도구를 빼고 실행한다.","시스템은 그 순간 동기화를 시작하고, 받은 뒤에도 그 값이 없으면 관리자에게 「매핑 확인」 알림을 보낸다.","「매핑 확인」 알림은 값마다 하루 한 번 가고, 수신 설정으로 끌 수 없다.","이 요청은 호출 이력과 서비스 사용 현황에 정상 요청으로 세고, 권한 항목별 보기에서는 「전체」에 들어간다."]}]},{"주제":"권한 설정·크레딧","개요":"서비스 사용자가 쓸 에이전트, 지식베이스, 도구의 접근 권한과 사용자별 한도, 크레딧 비율을 정하는 규칙과 그 값이 요청에 적용되는 시점을 다룬다.","묶음":[{"제목":"연결 전과 연결 끊김의 권한 설정","문장":["사용자·권한 API 가 연결되기 전에는 연결 외의 권한 설정을 쓸 수 없다.","연결 전 권한 설정에는 「연결된 서비스가 없습니다.」와 [API 연결](권한이 없으면 [연결 요청])만 있다.","연결 뒤 끊기면 마지막으로 받은 권한 체계와 사용자로 계속 운영한다.","연결이 끊긴 동안에도 권한 값 저장은 되고, 저장한 값은 다음 요청부터 적용된다.","다만 끊긴 동안에는 동기화가 실패해 서비스에서 바꾼 권한 체계, 사용자, 크레딧 한도가 들어오지 않는다.","다만 다시 연결되면 다음 동기화 때 그동안의 변경이 한꺼번에 반영된다."]},{"제목":"사용자에게 적용되는 권한 값","문장":["권한 설정의 대상은 서비스가 보낸 서비스 사용자이고, AGENTBASE 구성원의 권한은 시스템 설정의 구성원 권한이 정한다.","트리 맨 위 권한은 모든 서비스 사용자가 받는 권한이고 「전체」라고 부른다.","시스템은 서비스가 보낸 속성이 경로의 모든 항목 이름과 같은 가장 깊은 권한에 사용자를 매핑한다.","매핑된 권한에 지정하지 않은 값은 경로를 따라 상위 권한의 값을 받는다.","맞는 권한이 둘 이상이면 허용은 합치고 한도는 큰 값을 쓴다.","서비스가 승인한 적용 중인 추가 권한은 그 사용자의 권한에 더한다.","맞는 권한이 없는 사용자는 「전체」의 값만 받는다.","어디에도 값을 지정하지 않은 권한은 차단이다.","새로 만든 에이전트, 지식베이스, 도구는 접근 값 없이 만들어지고, 권한 설정에서 허용을 저장해야 서비스 사용자가 쓴다.","다만 속성 값이 권한 체계에 없으면 「전체」의 값만 적용하고 관리자에게 「매핑 확인」 알림을 하루 한 번 보낸다."]},{"제목":"접근 권한 판정","문장":["작업(에이전트, 지식베이스, 도구)마다 서비스 사용자가 쓸 권한을 허용 또는 차단으로 정하고, 도구는 동작마다 정한다.","하위 권한은 상위 권한이 허용한 범위 안에서 일부를 차단한다.","서비스 사용자가 에이전트 안의 지식베이스나 도구 하나에 권한이 없으면 요청을 거부하지 않고 그것만 빼고 실행한다.","삭제된 작업은 권한 목록에서 빠지고 그 작업에 지정한 값도 함께 지워진다.","에이전트에는 호출 한도가 없다."]},{"제목":"권한 값 저장과 적용 시점","문장":["권한 값 변경은 권한 설정 변경 권한이 필요하다.","권한이 있으면 [저장]으로 바로 적용하고, 없으면 [변경 요청]으로 바꾼 칸만 실어 승인을 요청한다.","권한 값은 저장한 순간(요청이면 승인한 순간) 다음에 들어온 요청부터 적용된다.","처리 중인 요청은 시작할 때의 권한으로 끝까지 처리한다.","저장 한 번에 바뀐 칸마다 작업 이력에 한 줄을 남기고, 다른 관리자에게 「권한 변경」 알림을 보낸다.","권한 설정의 편집 점유는 전체에 한 명이라 두 사람이 동시에 고칠 수 없다.","권한이 없는 구성원도 변경안을 쓰는 동안 편집 점유를 갖고, 요청을 보낸 뒤에는 점유를 놓는다.","3분 동안 조작이 없으면 점유를 풀고 저장하지 않은 값을 지운다.","권한 설정 전체의 승인 대기 요청은 한 건이고, 기다리는 동안 요청자는 그 칸을 고칠 수 없다.","승인되면 요청에 실은 칸만 적용하고, 기다리는 동안 다른 사람이 바꾼 칸은 되돌리지 않는다.","다만 승인을 기다리는 사이 대상 권한이 동기화로 없어지면 그 칸은 「대상 권한이 없어졌습니다.」로 보이고 승인해도 반영하지 않는다.","다만 승인할 칸이 하나도 남지 않으면 [승인]을 막는다.","다만 저장하지 않고 브라우저를 떠나면 변경을 버리고 「저장하지 않은 변경 n건은 반영하지 않았습니다.」를 알린다.","저장하지 않은 변경은 작업 이력에 남지 않는다."]},{"제목":"지식베이스·도구 호출 한도","문장":["허용한 권한마다 지식베이스는 사용자별 일일 요청 한도, 도구는 사용자별 시간당 호출 한도를 정한다.","지식베이스와 도구에 정한 전체 상한(모든 서비스 사용자 합계)이 사용자별 한도보다 먼저 적용된다.","한도 값 0은 차단이고, 빈 값은 제한 없음이다.","도구 시간당 한도는 매시 정각, 지식베이스 일일 한도는 매일 0시에 0부터 다시 센다.","한도를 넘은 호출에는 거절 문장을 돌려주고 나머지 노드는 계속 실행한다.","서비스 사용자는 막힌 지식베이스나 도구를 빼고 만든 답을 받고, 요청은 성공으로 남는다.","막힌 호출은 모니터링에서 에러가 아니라 차단으로 센다.","전체 상한을 사용자별 한도보다 작게 줄여도 저장하고, 실제 호출은 전체 상한이 먼저 막는다.","다만 한도를 세는 곳에 장애가 나면 통과시키지 않고 한도를 넘은 호출과 똑같이 그 호출만 막는다.","다만 이때 응답과 요청 상태는 한도 초과와 같고, 시스템 로그에 「한도 확인 불가」로 남는다.","다만 한도 확인 불가가 생기면 관리자에게 알리고, 30분 안의 같은 알림은 한 줄로 묶는다."]},{"제목":"크레딧 비율과 계산 단위","문장":["크레딧 비율은 호출 한 건의 모델 사용량과 도구 호출을 하나의 단위로 환산하는 값이다.","모델 배포는 모델 유형마다 단위 하나당 크레딧을 정한다.","LLM·VLM 은 입력 10만 토큰과 출력 10만 토큰 각각, 임베딩·리랭커는 입력 10만 토큰이 단위이다.","STT 는 오디오 1분, TTS 는 1K 글자, Image Generation 은 이미지 1장이 단위이다.","모델 배포 비율은 정수 0~100,000 이고, 0은 크레딧 없이 쓴다는 뜻이다.","처음 값은 LLM·VLM 입력 100, 출력 300, 임베딩·리랭커 100, STT 1, TTS 1, Image Generation 3이다.","비율 목록에는 배포중인 모델 배포만 오른다.","도구는 1회 호출을 단위로 정수 0~1,000 의 크레딧을 정하고, 동작마다 따로 정할 수 있다.","동작에 정하지 않은 값은 그 도구의 값으로, 도구 값도 없으면 등록 유형의 처음 값으로 센다.","지식베이스 검색은 도구 호출로 세지 않고, 그 검색에 쓴 임베딩·리랭커 모델 사용량으로 센다.","저장된 응답으로 답한 요청은 모델 사용량과 크레딧을 0으로 센다.","에이전트 테스트의 질문도 같은 방식으로 계산해 보이지만 서비스 사용자의 사용량에는 넣지 않는다.","모델 배포를 중지하거나 지워도 정한 비율은 남아, 다시 배포하면 그 값을 쓴다.","다만 실측 사용량 없이 토큰만 남은 기록은 STT 출력 150토큰을 1분, TTS 입력 1토큰을 2자, 이미지 출력 1,000토큰을 1장으로 어림한다."]},{"제목":"크레딧 비율 변경과 적용 시점","문장":["크레딧 비율 변경은 관리자 여부가 아니라 권한 설정 변경 권한으로 판정한다.","권한이 있는 구성원은 [저장]으로 바로 적용하고, 없는 구성원은 [변경 요청]으로 바꾼 칸만 실어 승인을 요청한다.","저장하거나 승인한 다음 시작한 요청부터 새 비율로 센다.","처리 중인 요청은 시작할 때의 비율로 끝까지 세고, 지난 호출은 다시 계산하지 않는다.","크레딧 비율의 편집 점유는 전체에 한 명이고, 3분 동안 조작이 없으면 풀린다.","크레딧 비율의 승인 대기 요청은 구성원마다 한 건이다.","요청을 보내면 요청에 실은 칸이 승인될 때까지 잠기고, 승인되면 그 칸만 적용한 뒤 잠금을 푼다.","바뀐 칸마다 작업 이력에 「크레딧 변경」 한 줄을 남긴다.","바로 저장했으면 실행자는 저장한 사람이고, 승인으로 적용했으면 실행자는 요청한 구성원이며 승인 관리자를 함께 적는다.","다만 거절되거나 요청자가 취소하면 저장된 값을 그대로 두고 잠금만 풀며, 관리자 알림에서도 그 요청이 빠진다.","다만 관리자가 바꾸는 사이 다른 구성원의 요청이 기다리면, 승인 때 요청에 실은 칸만 적용하고 관리자가 바꾼 칸은 그대로 둔다.","다만 두 구성원이 같은 칸을 요청하면 나중에 승인한 값이 남는다.","다만 승인하는 순간 대상 모델 배포나 도구가 삭제되었으면 [승인]을 막는다."]},{"제목":"서비스 사용자 크레딧 사용량과 한도 상태","문장":["이번 달 크레딧은 요청이 끝나는 순간 그 요청의 모델 사용량과 도구 호출을 비율로 환산해 더한다.","이번 달 사용량과 추가 지급은 매달 1일 0시에 0부터 다시 센다.","크레딧 한도와 추가 지급은 서비스가 정하는 보기 전용 값이고, 동기화할 때 바뀐다.","다만 서비스가 추가 지급을 알려 오면 그 사용자만 바로 반영한다.","한도 상태는 월 한도에 이번 달 추가 지급을 더한 값 대비 이번 달 사용률로 정한다.","사용률 80% 미만은 정상, 80% 이상은 한도 임박, 100% 이상은 한도 도달이다.","한도 도달 일시와 추가 지급 이력은 서비스가 보낸 값을 그대로 보인다.","추가 지급을 승인하는 사람은 서비스 관리자이고 AGENTBASE 구성원이 아니다.","AGENTBASE 는 서비스 사용자에게 한도 알림을 보내지 않고, 서비스 사용자에게 알리는 일은 서비스가 맡는다.","다만 동기화가 실패하면 직전에 받은 한도로 상태를 판정한다."]},{"제목":"크레딧 소진 처리","문장":["서비스는 크레딧이 남지 않은 사용자의 새 요청을 먼저 막는다.","서비스가 그래도 요청을 보내면 AGENTBASE 는 에이전트를 실행하지 않고 429 CREDIT_EXHAUSTED 「크레딧을 모두 사용했습니다.」를 돌려준다.","이 요청은 요청 수에 넣고 에러율에는 넣지 않는다.","다만 요청 도중 크레딧을 다 쓰면 AGENTBASE 가 그 자리에서 실행을 멈춘다.","이때 응답은 그때까지 만든 답과 「크레딧을 모두 사용해 응답을 멈췄습니다.」, 상태 credit_exhausted 를 담는다.","그 요청은 실패가 아니라 「크레딧 소진으로 중단」으로 남고, 그때까지 쓴 크레딧은 모두 센다.","그 요청은 요청 수에 넣고 에러율에는 넣지 않으며, 호출 이력의 그 줄에 중단 사유가 보인다.","그 사용자의 한도 상태는 「한도 도달」이 된다."]}]},{"주제":"서비스 API 오픈","개요":"서비스 API 와 에이전트별 오픈의 상태 전환, 실행 자원 점유, 오픈 중지 때 처리 중인 요청, API Key 의 효력, 저장된 응답을 다룬다.","묶음":[{"제목":"오픈 상태와 회차","문장":["서비스 API 오픈의 상태는 연결 전, 오픈 준비, 오픈됨, 오픈 중지 넷이다.","서비스 쪽을 처음 연결하면 0회차(오픈 준비)가 생기고, 오픈 전 서비스 설정 저장도 0회차에 남는다.","[서비스 API 오픈]은 서비스가 연결되어 있고 배포된 에이전트가 하나 이상 있어야 누를 수 있다.","오픈할 때 노드 풀 잔여 자원과 CPU·RAM 입력값이 노드 1대 규격 안인지 확인하고, 잔여 노드가 없는 노드 풀은 고를 수 없다.","오픈한 순간(요청이면 승인한 순간) 새 회차가 열리고, 오픈 중지로 그 회차가 닫힌다.","오픈 중지 상태에서 다시 오픈하면 새 회차가 열린다.","오픈한 에이전트가 하나도 없어도 서비스 API 를 오픈할 수 있고, 그동안 서비스가 부를 에이전트는 없다.","서비스 연결, 오픈, 오픈 중지, 서비스 설정 변경, 에이전트 오픈과 해제, 그룹 변경, API Key 발급·폐기는 서비스 API 오픈 권한이 필요하다.","권한이 없으면 같은 창에서 요청을 보내고, 관리자가 승인한 순간 적용한다.","서비스 하나의 승인 대기 요청은 한 건이고, 다른 구성원의 요청이 기다리면 서비스 설정의 선택지가 모두 막힌다.","다만 슈퍼 계정은 다른 구성원의 대기 요청이 있어도 오픈할 수 있다.","관리자가 [승인]을 누르는 순간 대상 상태와 요청자 권한을 다시 확인하고, 실행할 수 없으면 [승인]을 막는다.","다만 라이선스의 서비스 API 한도에 닿으면 새 오픈을 막고 「라이선스 서비스 API 한도에 닿아 오픈할 수 없습니다.」를 보인다.","라이선스가 만료되거나 한도에 닿아도 이미 오픈한 서비스 API 의 호출은 유지한다.","GPUBASE 에서 워크로드를 종료해도 오픈한 서비스 API 는 내리지 않고 호출이 끊기지 않는다."]},{"제목":"호출 시작과 실행 자원 점유","문장":["서비스는 오픈한 순간(요청이면 승인한 순간)부터 서비스 API 를 부를 수 있다.","실행 자원(노드 풀, CPU, RAM, 스토리지)은 오픈한 순간 잡고 오픈 중지까지 점유한다.","호출이 없어도 오픈한 동안에는 실행 자원을 점유한다.","서비스 노드 풀은 CPU 전용이라 GPU 를 잡지 않는다.","오픈하는 순간 오픈 스위치를 켜 둔 에이전트가 서비스의 그룹·모델 선택지에 함께 보인다."]},{"제목":"에이전트 오픈과 해제","문장":["에이전트 오픈 스위치는 오픈 준비와 오픈됨 상태에서만 켜고 끌 수 있다.","연결 전과 오픈 중지 상태에서는 오픈 스위치가 비활성이다.","스위치를 켜면 대표 모델을 고르고, 오픈한 순간(요청이면 승인한 순간)부터 그 에이전트를 부를 수 있다.","서비스 API 가 오픈된 중에 스위치를 켜면 그때부터 그 에이전트만 추가로 불린다.","스위치를 끄면 그 뒤 들어온 요청에 「{에이전트 이름} 에이전트가 오픈되지 않았습니다.」를 돌려주고 배포 회차는 유지한다.","보안 평가는 에이전트 오픈의 조건이 아니고, 평가 결과가 없어도 오픈할 수 있다.","보안 평가의 방어율은 참고값으로만 보인다.","대표 모델 선택지는 에이전트가 쓰는 모든 모델을 노드에서 많이 쓴 차례로 둔다.","같은 그룹에서 오픈했거나 오픈 승인을 기다리는 에이전트의 대표 모델은 고를 수 없다.","대표 모델 처음 값은 지난번 대표 모델이고, 오픈한 동안에는 바꿀 수 없다.","오픈 스위치가 막히면 오픈 중지, 연결 전, 그룹 없음, 모델 없음, 고를 대표 모델 없음, 남의 오픈 중지 요청 대기 차례로 먼저 걸린 이유 하나를 보인다.","다만 요청으로 오픈하면 승인할 때 고른 모델이 대표 모델이 된다.","다만 승인 전에 같은 그룹의 다른 에이전트가 같은 모델로 오픈되면 [승인]을 막는다.","다만 오픈 중지 요청이 승인을 기다리는 동안에는 에이전트를 새로 오픈할 수 없고 해제는 할 수 있다.","오픈한 에이전트가 없는 그룹은 서비스에 보이지 않고, 에이전트 이름은 서비스에 보이지 않는다."]},{"제목":"오픈한 에이전트의 배포 회차","문장":["에이전트 오픈의 단위는 배포 회차이다.","서비스 API 가 오픈된 동안 오픈한 에이전트는 배포 중지와 롤백이 막혀 배포 회차가 바뀌지 않는다.","배포 회차가 바뀌는 길은 오픈 해제 뒤 배포 중지, 또는 서비스 API 오픈 중지 상태에서 배포 중지뿐이다.","새 배포 회차는 오픈하지 않은 상태로 시작하고, 서비스가 부르려면 다시 오픈해야 한다.","프롬프트만 바꾼 경우는 배포 회차가 바뀌지 않아 오픈이 유지되고 계속 불린다.","다만 오픈 중지 상태에서 오픈해 둔 에이전트의 배포를 중지하면 그 오픈도 해제되고 작업 이력에 「오픈 해제(배포 중지)」가 남는다.","다만 그 에이전트는 다음에 서비스 API 를 오픈할 때 함께 열리지 않는다.","다만 오픈 중지 상태에서는 오픈해 둔 에이전트의 롤백을 막는다."]},{"제목":"오픈 중지와 처리 중인 요청","문장":["[오픈 중지]를 누른 순간(요청이면 승인한 순간) 새 호출을 바로 막는다.","중지 뒤 들어온 호출에는 503 SERVICE_API_STOPPED 「서비스 API 오픈이 중지되었습니다.」를 돌려준다.","중지할 때 처리 중인 요청은 끝까지 응답한다.","나누어 보내는 스트리밍 응답도 끝까지 보낸 뒤 연결을 닫는다.","끝까지 보낸 요청은 호출 이력에 성공으로 남고 모니터링 요청 수에 들어간다.","처리 중인 요청이 모두 끝나면 실행 자원을 돌려주고 그 회차를 닫는다.","작업 이력에 「실행 | 서비스 API | 오픈 중지」 한 줄이 남는다.","중지해도 에이전트별 오픈 설정은 지우지 않아, 스위치는 켜 둔 값을 보인 채 비활성이 된다.","다시 오픈하면 켜 둔 에이전트가 함께 오픈된다.","에이전트 하나만 해제하면 해제 뒤 들어온 요청부터 「{에이전트 이름} 에이전트가 오픈되지 않았습니다.」를 돌려준다."]},{"제목":"서비스 설정 변경","문장":["오픈된 동안에도 중지하지 않고 실행 자원을 뺀 서비스 설정을 바꿔 [저장] 한 번으로 함께 적용한다.","실행 자원과 노드 풀은 오픈 중지 상태에서만 바꾸고, 바꾼 값은 다음 오픈 때 그 값으로 잡는다.","서비스를 연결했으면 오픈 전에도 서비스 설정을 저장할 수 있고, 오픈할 때 저장한 값을 쓴다.","개인 지식베이스의 임베딩 모델을 바꾸면 개인 지식베이스 검색 DB 에 반영한다.","바꾼 칸마다 작업 이력에 「설정 변경」 한 줄을 남긴다."]},{"제목":"API Key 발급, 폐기, 만료","문장":["API Key 발급과 폐기는 서비스 설정에 담겼다가 [저장](권한이 없으면 승인)할 때 다른 변경과 함께 적용된다.","발급한 키는 적용한 순간부터 쓸 수 있다.","폐기한 키는 적용한 순간 막히고, 만료된 키는 만료 일시가 지난 순간 막힌다.","만료는 발급 때 고르며 최대 365일 또는 무기한이다.","키 개수는 제한하지 않아 여러 키를 동시에 쓸 수 있다.","키를 바꿀 때는 새 키를 발급해 서비스가 먼저 쓰게 한 뒤 옛 키를 폐기하면 끊김 없이 바뀐다.","옛 키에 유예 기간을 주는 교체 기능은 없다.","키 값은 발급 직후 한 번만 보이고 이후에는 끝 네 글자만 보이며, 시스템은 키 값을 저장하지 않는다.","발급과 폐기는 작업 이력에 「설정 변경」 줄로 키 끝 네 글자와 만료 일시를 남긴다.","만료 일시가 지나면 작업 이력에 「만료」 시스템 줄을 남긴다.","폐기되거나 만료된 키로 들어온 호출은 인증 실패 응답을 받는다.","인증에 실패한 호출은 서비스 사용 현황에 세지 않고 시스템 로그에만 남는다.","다만 사용 중인 키를 모두 폐기하면 서비스의 모든 호출이 인증 실패가 된다.","발급, 폐기, 만료 내역은 지우지 않고, 서비스 연결을 끊거나 오픈을 중지해도 남는다.","같은 이름으로 다시 발급해도 이전 키 내역은 따로 남는다.","키 내역은 화면에 이력 표시 기간 안의 것만 보이고, 리포트에는 모두 들어간다.","다만 다른 구성원이 서비스 설정을 편집 중이면 키를 발급하거나 폐기할 수 없다."]},{"제목":"저장된 응답","문장":["저장된 응답(응답 캐시) 설정은 서비스 설정과 에이전트 정보 양쪽에 있고, 처음 값은 둘 다 사용 안 함이다.","둘 다 사용일 때만 같거나 비슷한 질문에 모델을 실행하지 않고 저장한 응답을 돌려준다.","다만 서비스 쪽을 사용 안 함으로 두면 에이전트 쪽 값과 상관없이 저장한 응답을 쓰지 않는다.","서비스 쪽 설정은 서비스 API 오픈 권한을 거치고, 에이전트 쪽은 에이전트 정보 수정이라 권한이 필요 없다.","근거 문서가 바뀌거나 유효기간이 지나면 저장한 응답을 지운다.","저장한 응답으로 답한 요청은 요청 수에 넣고 모델 사용량과 크레딧은 0으로 센다.","저장한 응답으로 답한 요청은 호출 이력에 「저장된 응답」으로 남는다.","다만 개인 지식베이스를 쓴 응답과 민감 정보가 든 응답은 처음부터 저장하지 않는다."]}]},{"주제":"서비스 사용자 호출","개요":"서비스 사용자의 요청 한 건이 확인, 실행, 응답, 기록되는 차례와 막힐 때 돌려주는 응답, 사용자 상태별 처리, 호출을 받는 자원을 다룬다.","묶음":[{"제목":"요청 확인 차례","문장":["서비스 사용자의 요청은 API Key 확인, 오픈된 에이전트 확인, 사용자 권한으로 에이전트 사용 판정, 실행 차례로 처리한다.","앞 단계에서 막히면 에이전트를 실행하지 않고 막힌 이유를 응답한다.","권한은 요청에 실어 온 부서·직급 값으로 판정하고, 요청에 값이 없으면 마지막 동기화 값으로 판정한다.","요청에 대화 식별자가 없으면 새 대화로 처리한다.","실행 중에는 지식베이스·도구를 부를 때마다 권한과 한도를 확인하고 크레딧을 센다.","응답에는 실행 식별자가 함께 가고, 요청이 끝나면 사용 장부에 한 줄 남는다."]},{"제목":"막힐 때의 응답","문장":["API Key 가 없거나 맞지 않으면 인증 실패 응답으로 끝낸다.","오픈하지 않은 에이전트면 「{에이전트 이름} 에이전트가 오픈되지 않았습니다.」로 끝낸다.","사용자의 권한이 그 에이전트를 허용하지 않으면 「그 권한으로는 이 에이전트를 사용할 수 없습니다」로 끝낸다.","배포가 멈췄거나 응답하지 않으면 「{에이전트 이름} 에이전트가 응답하지 않습니다.」로 끝내고 에러로 센다.","서비스 API 오픈이 중지된 상태의 호출은 503 SERVICE_API_STOPPED 「서비스 API 오픈이 중지되었습니다.」로 끝낸다.","실행 중 노드가 실패하면 요청 전체를 끝내고 500 NODE_FAILED 「{노드} 노드가 실패해 응답을 멈췄습니다.」를 돌려주며 에러로 센다.","다만 에이전트 안의 지식베이스·도구 하나만 막히면 요청 전체를 거부하지 않고 그것만 빼고 실행한다.","이때 응답에는 뺀 지식베이스·도구와 이유 코드(PERMISSION_DENIED, RATE_LIMITED, AUTH_REQUIRED)를 담는다.","개인 인증이 안 된 도구도 빼고 실행하며, 응답에 인증 필요 안내를 넣는다.","사용자 검토 노드에 닿으면 202 REVIEW_PENDING 으로 실행 식별자, 안내 메시지, 선택지를 응답한다.","서비스가 재개 호출로 고른 분기를 보내면 그 분기로 실행을 이어 간다.","다만 검토 대기 시간이 지난 뒤 온 재개 호출은 410 REVIEW_EXPIRED 「검토 대기 시간이 지나 실행을 끝냈습니다.」로 끝낸다."]},{"제목":"새 사용자, 일시 정지, 삭제된 사용자","문장":["동기화 전의 새 사용자 요청은 요청에 실려 온 부서·직급 값으로 판정해 정상 응답한다.","새 사용자의 요청은 서비스 사용 현황에 바로 세고, 서비스 사용자 목록에는 다음 동기화 뒤에 보인다.","다만 새 사용자의 부서 값이 권한 체계에 없으면 「전체」의 값으로 처리하고 동기화를 시작한다.","동기화로 「삭제됨」이 된 사용자의 요청은 실행하지 않고 403 USER_INACTIVE 「사용할 수 없는 사용자입니다.」를 돌려준다.","삭제된 사용자의 요청은 에러가 아닌 차단으로 세고, 시스템 로그에 「삭제된 사용자」로 남긴다.","서비스가 사용자 상태를 inactive 로 보내면 「일시 정지」로 두고, 그 사용자의 요청도 403 USER_INACTIVE 로 막아 차단으로 센다.","일시 정지 사용자의 사용량, 크레딧 기록, 개인 지식베이스, 개인 도구는 그대로 둔다.","다만 서비스가 다시 active 를 보내면 그 순간부터 요청을 받는다."]},{"제목":"좋아요·싫어요 반영","문장":["서비스가 좋아요·싫어요를 보내면 실행 식별자로 원래 요청을 찾아 받는 즉시 반영한다.","반영 대상은 그 에이전트 모니터링과 서비스 사용 현황의 만족도이다.","만족도는 평가한 답변 가운데 좋아요의 비율이고, 싫어요 사유는 「싫어요 사유」 보기에 모인다.","다만 없는 실행 식별자로 보내면 「실행이 없습니다」를 돌려주고 만족도에 넣지 않는다.","권한으로 걸러 봐도 만족도는 거르지 않는다."]},{"제목":"호출을 처리하는 자원","문장":["서비스 API 를 오픈할 때 잡은 실행 자원이 호출을 받아 인증하고 에이전트에 넘기며 대화를 저장한다.","답을 만드는 일은 각 에이전트와 모델 배포가 점유한 자원이 한다.","실행 자원은 노드 풀, CPU, RAM, 스토리지이고, 서비스 노드 풀은 CPU 전용이라 GPU 가 없다.","개인 지식베이스와 개인 도구는 서비스 설정에서 따로 정한 자원을 쓰고, 오토 스케일링 설정에 따라 레플리카가 늘고 준다.","다만 실행 자원 사용률이 시스템 자원 알림 기준(처음 값 90%)을 넘으면 그 순간 구성원 전원에게 「자원 사용률 초과」 알림이 한 번 간다.","다만 모델 배포가 늘어나야 하는데 자원이 모자라면 지금 레플리카로 계속 응답하고, 확장은 자원이 반환될 때까지 기다린다.","자원이 반환되면 시스템이 기다리던 확장을 자동으로 진행한다.","확장을 기다리는 사이 응답 시간이 늘면 응답 지연 알림으로 드러난다."]}]},{"주제":"서비스 모니터링","개요":"서비스 호출 결과가 서비스 사용 현황과 자원 사용 현황에 기록, 집계, 갱신되는 기준과 요청 급증·응답 지연 알림 판정, 기록 보존을 다룬다.","묶음":[{"제목":"모니터링 지표 갱신","문장":["요청이 끝나는 즉시 사용 장부에 기록하고, 화면이 다음에 새로 그려질 때 수치에 들어간다.","처리 중인 요청은 세지 않는다.","요청은 받은 시각의 칸에 들어가므로, 오래 걸린 요청은 끝난 뒤 지난 칸의 값을 늘린다.","진행 중인 마지막 칸은 끝난 요청만 들어간 값이라 칸이 끝날 때까지 늘어나며 「집계 중」으로 표시한다.","화면을 열어 둔 동안 상단바 갱신 주기(15초, 30초, 1분, 수동 가운데 처음 값 15초)마다 다시 그린다.","기간 필터를 다시 고르거나 화면을 다시 열면 그 순간까지 끝난 요청이 모두 들어간다.","서비스 사용자 목록의 사용량과 크레딧도 같은 때 바뀐다.","다만 갱신 주기가 수동이면 [즉시 수집]을 누를 때만 다시 그린다.","다만 서비스가 좋아요·싫어요를 늦게 보내면 받는 즉시 원래 요청이 있던 칸의 만족도에 반영되어 지난 칸 값이 바뀐다.","다만 시험 호출은 서비스 사용 현황, 크레딧, 서비스 사용자 사용량 어디에도 세지 않는다.","시험 호출은 서비스 API 를 오픈한 뒤에만 된다."]},{"제목":"집계 칸 폭","문장":["칸 폭은 고른 기간 길이로 정하고, 모든 모니터링 화면이 같은 표를 쓴다.","고른 기간이 6시간까지면 5분, 7일까지면 1시간, 30일까지면 12시간, 그보다 길면 하루 칸이다.","자원 사용 현황의 CPU·RAM 사용률도 서비스 사용 현황과 같은 칸 폭을 쓴다.","요청 급증과 응답 지연 알림은 칸 폭과 상관없이 실제 시각에 맞춘 5분 구간으로 판정한다."]},{"제목":"요청 수, 에러율, 차단 세는 기준","문장":["API 가이드의 호출 현황과 서비스 사용 현황은 같은 사용 장부를 세므로, 같은 기간이면 전체 요청 수가 같다.","요청 한 건은 그 요청에 쓴 API Key 하나에 들어간다.","에러율은 에이전트나 연결 자원이 실패한 요청만 센다.","권한·한도로 막힌 호출과 일시 정지·삭제된 사용자의 요청은 에러가 아니라 차단으로 따로 센다.","차단 수는 에러율과 따로 보인다.","크레딧 소진으로 멈춘 요청은 요청 수에 넣고 에러율에는 넣지 않는다.","응답 시간은 성공 요청을 기준으로 잰다.","다만 API Key 가 맞지 않아 들어오지 못한 호출은 사용 현황에 세지 않고 시스템 로그에만 남긴다.","권한으로 거르면 요청, 성공률, 사용자, 지표 카드는 그 권한의 사용자만 센다.","다만 만족도는 평가에 계정이 없어 권한으로 거르지 않는다.","서비스 사용 현황을 보는 일은 작업 이력에 남지 않는다."]},{"제목":"요청 급증·응답 지연 알림","문장":["시스템은 5분 구간이 끝날 때마다 요청 급증과 응답 지연을 판정해 그 서비스의 생성자와 관리자에게 알린다.","5분 구간 요청 수가 직전 1시간 5분 평균의 요청 급증 기준(처음 값 3배) 이상이면 요청 급증이다.","5분 구간 응답 시간 p95 가 직전 1시간 p95 의 응답 지연 기준(처음 값 2배) 이상이면 응답 지연이다.","두 기준은 관리자가 시스템 설정에서 1.5~10배 사이로 바꾼다.","알림의 [상세 보기]는 사건 앞뒤 1시간을 연다.","다만 30분 안에 같은 대상에서 같은 알림이 다시 나면 한 줄로 묶고 「같은 알림 n건」으로 보인다.","다만 직전 1시간의 기록이 없으면 판정하지 않는다."]},{"제목":"자원 사용 현황과 원인 추적","문장":["자원 사용 현황은 서비스 요청이 부른 모델 배포, 지식베이스, 도구별 사용 현황과 실행 자원 사용률을 보인다.","개인 지식베이스와 개인 도구는 각각 실행 단위 하나로 요청 수, 응답 시간 p95, CPU·RAM 사용률, 레플리카 증감을 보인다.","개인 지식베이스·도구 하나하나와 사용자별 사용량은 자원 사용 현황에서 세지 않는다.","GPU 를 쓰지 않으면 CPU·RAM 줄만 보인다.","서비스 모니터링은 서비스 지표와 호출 자원 표까지 보이고, 원인은 에이전트 모니터링으로 이동해 본다.","모니터링은 측정값만 보이고 권고 문장은 두지 않는다."]},{"제목":"기록 보존","문장":["서비스 사용 현황과 호출 이력은 아무도 지우지 않고 계속 남는다.","화면에는 시스템 설정의 이력 표시 기간(처음 값 180일) 안의 기록만 보인다.","리포트와 감사 이력 내보내기에는 이력 표시 기간과 상관없이 모든 기록이 들어간다.","이력 표시 기간을 줄였다가 다시 늘리면 지난 기록이 다시 보인다.","서비스에서 삭제된 사용자의 지난 사용량과 크레딧 기록도 남고, 사용자 목록에는 「삭제됨」으로 보인다."]}]},{"주제":"권한·승인","개요":"구성원 권한 판정, 요청을 보낸 뒤의 잠금과 취소, 관리자 검토와 승인 즉시 실행, 승인 순간 재확인, 동시 처리를 다룬다.","묶음":[{"제목":"권한 판정과 요청 대상","문장":["구성원 권한 유형은 서비스 API 오픈, 다운로드, 컴퓨팅 자원 사용, 리더보드 등록, 권한 설정 변경, 라벨링 검수 여섯이다.","관리자는 여섯 권한을 모두 가진다.","조작마다 권한 유형 하나로 판정하고, 권한이 있으면 버튼이 [{동작}], 없으면 [{동작} 요청]이다.","라벨링 검수는 요청이 없고, 권한이 없으면 할 수 없다.","학습 중지는 컴퓨팅 자원 사용 요청 대상이다.","배포 중지는 요청 대상이 아니고, 권한과 관계없이 확인 뒤 바로 중지한다.","자원을 점유하기 전 취소인 [실행 취소]와 [예약 취소]도 요청을 거치지 않는다.","값을 정하는 일은 설정 창을 거치고, 권한이 없으면 마지막 버튼이 [다음]이 되어 요청 창으로 넘어간다.","값이 없는 일(학습 중지, 리더보드 등록 해제, 다운로드, 오픈 중지, 에이전트 오픈·오픈 해제)은 요청 창이 바로 열린다.","요청 창은 선택 메모(500자)를 받고, [요청]하면 승인 대기가 되며 관리자 전원에게 승인 요청 알림이 간다.","오토 스케일링은 레플리카를 늘리는 조작만 요청이고, 줄이거나 기준만 바꾸면 바로 저장한다.","설정 창을 연 상태에서 권한을 받으면 마지막 버튼이 [다음]에서 [{동작}]으로 즉시 바뀐다."]},{"제목":"승인 대기 단위","문장":["승인 대기 요청은 단위마다 1건이다.","컴퓨팅 자원 사용 요청은 작업 1개에 1건이고, 학습 실행과 학습 중지처럼 일이 달라도 함께 센다.","리더보드 등록·해제는 모델 배포 1개에 1건이다.","권한 값 변경은 권한 설정 전체에 1건, 크레딧 비율 변경은 크레딧 관리 전체에 1건이다.","서비스 쪽 요청은 서비스 1개에 1건이고, 서비스 API 연결과 사용자·권한 API 연결은 따로 1건씩이다.","다운로드 요청은 구성원마다 1건이라 다른 구성원의 요청이 대기해도 막지 않는다.","단위 안에 다른 구성원의 요청이 대기하면 같은 일의 버튼은 관리자를 포함해 비활성이다.","이때 「{요청자}님의 {일} 요청이 관리자의 승인을 기다리고 있습니다.」를 보인다."]},{"제목":"승인 대기 중 잠금","문장":["요청이 대기하는 동안 요청한 설정 값은 요청자, 다른 구성원, 관리자 모두 고칠 수 없다.","대기 중인 요청이 있는 대상은 삭제할 수 없다.","요청자에게는 같은 자리 버튼이 [{일} 요청 취소]로 바뀌고, 「{일} 요청이 관리자의 승인을 기다리고 있습니다.」가 보인다.","같은 대상의 다른 컴퓨팅 자원 버튼은 모두 비활성이다.","컴퓨팅 자원 요청이 승인 대기 중이면 작업 상태는 대기(승인 대기)이고 자원은 잡지 않는다.","권한 설정 변경 요청을 보내면 요청자는 편집 점유를 즉시 놓는다.","권한 설정 변경 요청이 대기하는 동안에는 요청한 값을 아무도 고칠 수 없다."]},{"제목":"요청 취소와 자동 취소","문장":["요청자가 [{일} 요청 취소]를 고르면 확인 창 뒤 요청이 취소되고, 요청 취소는 요청자 본인만 한다.","취소된 요청은 관리자의 알림 목록과 알림 수에서 즉시 빠지고, 취소 알림은 누구에게도 보내지 않는다.","승인 대기로 멈춰 있던 학습과 모델 배포는 요청 전 상태로 돌아간다.","감사 이력에는 결과 「요청 취소」, 처리자 요청자 본인으로 남는다.","단위 안의 요청이 취소되는 순간 다른 구성원의 막힌 버튼이 풀린다.","다만 관리자가 요청자에게 그 권한을 주면 그 권한으로 보낸 대기 요청은 모두 자동 취소된다.","자동 취소 사유는 「권한이 생겨 요청 없이 실행할 수 있습니다.」이고, 처리자는 권한을 바꾼 관리자다.","권한을 회수해도 대기 요청은 그대로 두고, 승인되었으나 아직 쓰지 않은 승인은 끝날 조건까지 유효하다.","구성원을 관리자로 지정해도 그 구성원의 기존 대기 요청은 남고, 본인이 직접 승인하거나 거절한다.","다만 자원 한도 변경 요청은 AGENTBASE 권한과 무관해, 권한이 생기거나 관리자로 지정되어도 자동 취소하지 않는다."]},{"제목":"검토와 승인 즉시 실행","문장":["관리자가 [검토]를 고르면 검토 창에 요청 내용, 요청자, 메모가 보인다.","검토 진입점은 알림 패널의 검토할 요청, 홈 승인 대기 위젯, 시스템 설정 구성원 권한, 요청 대상 상세의 [요청 검토] 넷이다.","네 진입점은 모두 같은 검토 창을 연다.","관리자가 [승인]하면 시스템이 요청한 값 그대로 즉시 실행하고, 요청자에게 승인 알림을 보낸다.","승인 뒤 실행하는 일은 승인 시각이 곧 실행 시각이다.","승인 순간 노드 풀 자원이 모자라면 대기(자원 부족)로 들어가고, 자원이 돌아오는 순간 자동으로 시작한다.","다만 다운로드는 승인 뒤 요청자가 직접 받는다.","자원 한도 변경은 AGENTBASE 관리자가 검토하지 않고, GPUBASE 에서 승인해야 적용된다.","[거절]은 검토 메모(500자)에 거절 사유가 있어야 하고, 없으면 「거절하려면 검토 메모에 거절 사유가 있어야 합니다.」를 보인다.","거절하면 대상은 요청 전 상태로 돌아가고, 새로 만들려던 모델 배포는 만들지 않은 것으로 처리한다.","거절하면 작업 이력에 반영 상태 「반려({사유})」가 남고, 요청자에게 거절 알림이 간다.","다만 예약이 담긴 요청을 승인하는 순간 예약 일시가 이미 지났으면 [승인]은 비활성이고 「예약 일시가 지나 승인할 수 없습니다.」를 보인다.","이때 [거절]은 할 수 있고, 요청자는 요청을 취소한 뒤 새 시점으로 다시 요청한다."]},{"제목":"승인 순간 재확인","문장":["검토 창은 열 때와 [승인]을 누르는 순간 대상 상태와 요청자 권한을 다시 확인한다.","대상 상태가 바뀌어 요청한 일을 실행할 수 없으면 [승인]과 [거절]을 비활성으로 두고 사유를 보인다.","사유 문장의 예는 「배포가 실패 상태라 요청을 실행할 수 없습니다.」다.","이 경우 시스템이 요청을 자동 취소하고, 감사 이력에 결과 「요청 취소」와 사유, 처리자 「시스템」으로 남긴다.","요청자에게는 승인 결과 알림으로 자동 취소 사유를 보낸다.","권한 값 변경 요청에서 대상 칸이 동기화로 없어졌으면 그 칸은 반영하지 않고, 남은 칸이 없으면 [승인]을 막는다.","관리자가 AI 개발자로 바뀌는 순간 열어 둔 검토 창의 [승인]과 [거절]은 비활성이 된다."]},{"제목":"동시 검토","문장":["관리자 두 명이 같은 요청을 열면 먼저 처리한 판단 하나만 남는다.","나중에 처리하려는 검토 창은 [승인]과 [거절]이 비활성이 되고 이유를 보인다.","이유는 「{이름}님이 이미 승인한 요청입니다.」, 「{이름}님이 이미 거절한 요청입니다.」, 「요청자가 취소한 요청입니다.」 가운데 하나다.","창 제목은 바뀌지 않는다.","감사 이력에는 실제로 처리한 사람과 일시만 남는다."]},{"제목":"다운로드 승인 범위","문장":["폴더나 여러 파일의 다운로드 승인은 요청할 때의 파일 목록과 각 파일의 회차에 고정된다.","승인 뒤 그 폴더에 추가된 파일은 승인에 들어가지 않는다.","다운로드 승인은 1회 다운로드, 승인 후 7일, 파일 회차 변경 가운데 먼저 오는 때 끝나고 감사 이력 결과는 「만료」다.","관리자가 직접 받은 다운로드는 감사 이력의 승인자가 그 관리자다."]},{"제목":"감사 이력 기록","문장":["승인 요청의 상태는 승인 대기, 승인, 거절, 요청 취소 넷이다.","감사 이력의 결과는 승인 대기, 실행, 실행 전, 거절, 요청 취소, 만료, 적용 일곱이다.","감사 이력 대상은 승인 요청, 다운로드, 권한 설정 저장, 구성원 권한 변경이다.","관리자가 구성원의 구분이나 권한을 바꾸면 저장 없이 즉시 적용되고 감사 이력에 결과 「적용」으로 남는다.","구분과 권한 값의 변경은 감사 이력 한 건에 함께 남고, 변경 알림은 보내지 않는다.","시스템 설정의 변경은 관리자만 하므로 승인 요청을 거치지 않는다."]}]},{"주제":"알림","개요":"알림 종류별 받는 사람, 작업 종료 알림과 묶음, 수신 설정, 사용률과 운영 사건의 판정 기준, 알림 보관과 삭제된 대상, 영향 범위를 다룬다.","묶음":[{"제목":"받는 사람","문장":["알림은 AGENTBASE 안의 시스템 알림으로만 보내고, 공지, 메일, 메신저로 보내지 않는다.","승인 요청은 관리자 전원, 승인 결과는 요청자, 검수 요청은 검수자에게 보낸다.","회차 시작은 모든 구성원에게 보낸다.","자원 사용률 초과와 저장 용량 알림은 구성원 전원에게 보낸다.","권한 변경과 매핑 확인은 관리자에게 보낸다.","자동 복구와 중단 같은 오류 알림, 응답 지연, 요청 급증, 연결 자원 변경은 모든 구성원에게 보낸다.","데이터 새 회차와 데이터셋 새 버전은 그 데이터를 쓰는 작업마다 생성자와 관리자 전원에게 한 건씩 보낸다.","작업 시작과 작업 종료는 실행자와 관리자에게 보낸다.","오케스트레이션 종료는 요청자 본인에게만 보낸다.","권한 유형은 받는 사람을 정하는 데 쓰지 않고, 권한이 있는 AI 개발자도 알림에서는 AI 개발자와 같다."]},{"제목":"작업 종료 알림과 묶음","문장":["작업이 끝나면 실행자와 관리자에게 작업 종료 알림이 가고, 알림 패널의 시각 구획(오늘, 어제, 최근 7일)에 쌓인다.","다만 작업이 끝날 때 실행자가 그 작업 화면을 보고 있으면 실행자에게는 알림 없이 화면 안내만 보인다.","작업 종료 알림은 상단바 갱신 주기와 상관없이 끝나는 즉시 온다.","같은 대상의 같은 종류 알림이 30분 안에 다시 나면 「같은 알림 n건, 처음 {일시}」로 한 줄에 묶는다.","관리자의 승인 요청 알림은 따로 저장하지 않고, 알림 패널을 열 때 대기 중인 요청에서 만든다."]},{"제목":"수신 설정","문장":["구성원이 [수신 설정]에서 알림 종류를 끄면 즉시 저장되고, 이미 온 알림까지 목록과 알림 수에서 빠진다.","수신 설정은 구성원마다 따로다.","끈 알림은 지우지 않고 거르기만 하므로, 다시 켜면 최근 7일 안의 것이 다시 나타난다.","끌 수 없는 알림은 승인 요청(관리자), 검수 요청(검수자), 회차 시작(모든 구성원), 매핑 확인(관리자) 넷이다.","끌 수 있는 묶음은 내 작업, 자원과 연결, 관리자 셋이고 관리자 묶음은 관리자에게만 있다.","오류 알림은 구성원 전원이 받되, 각자 자원과 연결 묶음에서 끈다.","다만 저장 용량 알림을 꺼도 스토리지 95% 생성 차단은 그대로이고, 막힌 버튼이 이유를 보인다.","관리자가 AI 개발자로 바뀌면 관리자 묶음은 사라지고, 그 값은 다시 관리자가 될 때 쓰인다.","시스템 설정 운영 설정에는 수신 설정을 두지 않는다."]},{"제목":"사용률과 운영 사건 알림 판정","문장":["GPU, CPU, RAM 사용률이 시스템 자원 알림 사용률(처음 값 90%)을 넘는 순간 구성원 전원에게 한 번 보낸다.","스토리지는 스토리지 알림 사용률(처음 값 80%)에 닿을 때 한 번, 95% 에 닿을 때 한 번 더 보낸다.","기준 이상인 동안은 같은 알림을 반복해 보내지 않고, 그 알림은 조치가 필요한 알림 구획에 남는다.","사용률이 기준 아래로 내려가면 그 알림은 조치가 필요한 알림 구획에서 빠진다.","응답 지연과 요청 급증은 5분 구간이 끝날 때마다 판정해 모든 구성원에게 보낸다.","응답 시간 p95 는 요청 100건 가운데 느린 쪽 5건이 시작되는 경계 시간이다.","응답 지연은 5분 구간의 응답 시간 p95 가 이전 1시간 p95 의 2배(처음 값) 이상일 때 보낸다.","요청 급증은 5분 구간 요청 수가 이전 1시간의 5분 평균 요청 수의 3배(처음 값) 이상일 때 보낸다.","관리자는 기준값을 시스템 설정 운영 설정에서 바꾸고, [저장] 뒤 다음 판정부터 적용된다.","기준 범위는 시스템 자원 50~99%, 스토리지 50~94%, 응답 지연과 요청 급증 1.5~10배다.","스토리지 95% 는 고정 차단 기준이라 알림 사용률을 95% 이상으로 정할 수 없다."]},{"제목":"알림 보관과 삭제된 대상","문장":["알림 패널은 최근 7일의 알림을 개수로 자르지 않고 모두 보인다.","7일이 지난 알림은 패널에서 빠지고, 지난 일은 작업 이력으로 확인한다.","다만 알림이 가리키던 작업이 삭제되어도 알림은 지우지 않는다.","삭제된 작업의 알림은 [상세 보기]와 [영향 범위]가 비활성이고 「삭제된 작업입니다.」를 보이며, 골라도 이동하지 않는다.","조치가 필요한 알림 구획에 있던 알림은 대상이 없어지는 순간 시각 구획으로 내려간다.","조치가 필요한 알림은 중단, 지금도 기준 이상인 자원, 저장 용량, 모델 배포가 쓰던 커밋의 삭제, 도구 호출 불가다.","도구 호출 불가는 배포중인 에이전트가 연결한 도구를 부를 수 없을 때다."]},{"제목":"확인 상태","문장":["구성원이 알림 한 건을 고르거나 [확인함]으로 바꾸면 그 알림이 안 읽은 수에서 빠진다.","[모두 확인]은 검토할 요청을 뺀 알림만 확인함으로 바꾸고, 검토할 요청은 [검토]로 판단해야 빠진다.","확인 상태는 구성원마다 따로다.","승인을 기다리는 내 요청은 안 읽은 수에 넣지 않는다."]},{"제목":"영향 범위","문장":["구성원이 알림의 [영향 범위]를 고르면 알림 대상 자원을 쓰는 작업을 연결 사슬을 따라 보인다.","연결 사슬은 서비스 API 오픈, 에이전트, 모델 배포·지식베이스·도구 차례다.","간접 대상인 서비스 API 오픈과 그 대상을 부르는 에이전트까지 영향 범위에 넣는다."]}]},{"주제":"홈·대시보드","개요":"홈과 대시보드의 배치 저장 기준, 위젯 수치를 다시 모으는 주기, 위젯마다 세는 대상과 집계 기준을 다룬다.","묶음":[{"제목":"배치 저장 기준","문장":["홈과 대시보드 배치는 GPUBASE 계정의 구분(관리자, AI 개발자)을 기준으로 정한다.","관리자인 계정은 관리자 배치, AI 개발자는 AI 개발자 배치로 시작한다.","관리자로 지정된 AI 개발자는 관리자 홈 배치와 관리자 대시보드 템플릿을 쓴다.","홈 위젯 배치는 구분마다, 오케스트레이터 연결 여부마다 따로 저장한다.","홈 배치는 이 브라우저에 저장하고 계정에는 저장하지 않아, 다른 브라우저에서는 처음 배치로 보인다.","구분이 바뀌면 바뀐 구분의 배치를 열고, 앞 구분에서 고친 배치는 다시 그 구분이 되면 돌아온다.","오케스트레이터 연결이 끊기면 홈은 작업 전환 위젯 배치로 바뀌고, 입력 위젯 배치는 다시 연결될 때 쓴다.","대시보드는 템플릿 단위이고, 템플릿은 계정마다 저장한다.","기본 제공 템플릿은 관리자 여섯, AI 개발자 둘이다.","다만 관리자에서 AI 개발자로 바뀌면 관리자 기본 템플릿 넷은 빠지고 내가 저장한 템플릿은 남는다.","AI 개발자도 관리자와 같은 위젯을 모두 고를 수 있다.","대시보드 편집 중 초안은 자동으로 남고, [저장]하면 지운다.","저장하지 않고 나갔다가 다시 편집하면 남은 초안을 이어 쓴다.","GPUBASE 그룹 관리자의 관리자 대시보드는 시스템 관리자와 같은 전체 범위를 집계한다."]},{"제목":"위젯 수치 갱신 주기","문장":["홈과 대시보드의 숫자와 상태는 상단바에서 고른 갱신 주기마다 다시 모은다.","갱신 주기는 15초(처음 값), 30초, 1분, 수동 가운데 고른다.","고른 주기는 이 브라우저에 저장되어 모든 화면에 같게 적용된다.","마지막으로 모은 시각은 상단바에 보인다.","서비스 API 로 들어온 호출은 요청이 끝난 뒤 다음 수집 때 반영된다.","요청 수와 응답 시간은 알림 판정과 같은 5분 구간으로 모으고, 진행 중인 구간의 값은 그 구간이 끝나야 확정된다.","다만 수동이면 [즉시 수집]을 누를 때만 바뀌고, 실행이 끝나도 그 전까지 마지막으로 모은 상태로 남는다.","다만 작업 종료 알림은 갱신 주기와 상관없이 작업이 끝나는 순간 온다.","대시보드 수치는 머리 기간 필터(처음 값 최근 30일)의 합이고, 기간을 고정한 위젯은 그 기간의 합이다."]},{"제목":"상용 API 비용 집계","문장":["상용 API 비용은 이번 달 1일부터 마지막 수집 시각까지 쓴 금액이다.","금액은 공급사의 입력·출력 토큰 요금을 원으로 바꾼 값이다.","공급사 요금은 1시간마다 모으고, 마지막 수집 시각은 공급사 요금을 마지막으로 모은 시각이다.","홈 위젯과 대시보드 위젯은 같은 값을 보인다.","다만 공급사에서 요금을 모으지 못하면 마지막으로 모은 값과 그 수집 시각을 그대로 보인다."]},{"제목":"실행중 작업과 자원 대기 작업 세는 기준","문장":["실행중 작업은 상태가 실행중인 학습, 전체 실행과 표본 실행, 검색 DB 생성과 업데이트만 센다.","배포중인 모델 배포, 지식베이스, 도구, 데이터 파이프라인, 에이전트와 서비스 API 오픈은 실행중 작업에 넣지 않는다.","자원 대기 작업은 자원 부족, 예약, 피크외 시간으로 기다리는 작업과 작업마다 필요한 자원을 센다.","학습과 모델 배포는 GPU 를, 지식베이스·도구·데이터 파이프라인은 CPU 와 RAM 을 기다린다.","승인 대기 작업은 자원 대기 작업에 넣지 않는다.","다만 실행 일정이 있는 데이터 파이프라인은 다음 실행을 기다리는 동안 상태가 「대기」이다.","그 데이터 파이프라인은 이미 자원을 점유하고 있어 자원 대기 작업 수와 대기 필터에서 뺀다.","홈의 실행중 작업, 자원 대기 작업, 문제 발생은 시스템 자원 관리 작업 목록과 같은 셈이다.","실패한 작업은 자원을 반환하므로 GPU 점유와 호출 없는 점유에 넣지 않는다.","실행 작업 위젯은 경과 시간만 보이고 남은 시간은 계산하지 않는다."]},{"제목":"서비스 지표 위젯 집계","문장":["서비스 지표 위젯은 선택한 기간의 요청 수, 성공 응답, 에러, 응답 시간, 만족도, 서비스 사용자 수를 집계한다.","응답 시간은 성공 요청 기준이고, 만족도는 평가한 답변 가운데 좋아요 비율이다.","권한 거부와 호출 한도 초과로 막힌 요청은 에러율에 넣지 않고 차단 수로 따로 센다.","에이전트 호출 순위는 서비스 API 로 들어온 최근 30일 호출만 세고 테스트 호출은 넣지 않는다.","서비스 모니터링은 서비스 지표와 호출 자원 표까지 보이고, 문제 원인은 에이전트 모니터링으로 이동해 본다.","자원 대비 호출 위젯은 호출 비중을 자원 비중으로 나눈 값으로 정상, 경고, 위험을 가른다.","경고 기준은 0.3, 0.5, 0.7배 미만(처음 값 0.5), 위험 기준은 1.5, 2, 3배 이상(처음 값 1.5) 가운데 위젯마다 고른다.","주소만 등록한 외부 엔드포인트와 상용 API 는 모델 배포 자원 대비 호출 대상에서 뺀다."]}]},{"주제":"리포트","개요":"리포트 생성의 진행과 실패 처리, 담기는 기록의 범위와 내용 고정, 다운로드 권한, 삭제를 다룬다.","묶음":[{"제목":"리포트 생성과 진행","문장":["구성원이 이름, 설명, 대상, 수집 기간을 넣고 [생성]하면 리포트가 「대기」로 목록에 들어간다.","리포트 생성은 권한이 필요 없고 자원을 점유하지 않는다.","동시에 만드는 리포트 수는 제한하지 않는다.","생성을 시작하면 상태는 대기, 실행중을 거쳐 끝나면 종료가 된다.","구성원이 다른 화면으로 가도 생성은 계속된다.","생성이 끝나면 생성자에게 작업 종료 알림이 간다.","다만 생성자가 리포트 화면에 있으면 알림 대신 「{이름} 리포트 생성이 완료되었습니다.」만 보인다.","다만 생성에 실패하면 상태가 「실패」가 되고 실패 사유를 함께 보인다.","실패한 리포트는 받을 수 없고 다시 만들어야 한다.","대기·실행중인 리포트를 [중지]하면 파일을 만들지 않고 상태는 「중지」가 된다.","리포트 중지는 생성자와 관리자만 할 수 있다.","이름은 100자 이하이고 「/」를 쓸 수 없으며, 리포트 전체에서 같은 이름을 막는다.","리포트 목록은 모든 구성원이 함께 본다."]},{"제목":"담기는 기록과 내용 고정","문장":["수집 기간은 최근 7일, 30일, 90일, 사용자 지정 가운데 고르고 처음 값은 최근 30일이다.","리포트에는 고른 수집 기간 안의 기록이 이력 표시 기간과 상관없이 모두 들어간다.","작업 이력 화면은 표시 회차 수만큼만 보이지만 리포트는 그보다 오래된 회차도 담는다.","대상 「감사 이력」은 관리자만 고를 수 있다.","리포트 내용은 생성한 시점의 데이터로 고정되어 언제 내려받아도 같다.","생성 뒤 대상 작업이 삭제되어도 내려받는 내용은 바뀌지 않는다.","작업이 삭제되어도 그 작업의 기록은 리포트 적재분으로 남는다.","다만 수집 기간 안에 기록이 없으면 머리만 담긴 파일을 만든다."]},{"제목":"리포트 다운로드","문장":["종료 상태의 리포트만 받을 수 있다.","파일 형식은 생성할 때가 아니라 받을 때 CSV 나 PDF 로 고른다.","같은 리포트를 두 형식으로 각각 받을 수 있다.","다운로드는 다운로드 권한을 거치고, 받은 일은 감사 이력에 「다운로드」로 남는다.","권한이 없는 구성원은 [다운로드 요청]을 보내 관리자 승인을 받는다.","승인을 기다리는 동안 그 리포트의 다운로드는 요청자에게 비활성이다.","승인되면 요청자에게 알림이 가고, 승인 후 7일 안에 한 번 받을 수 있다.","다만 감사 이력을 담은 리포트는 다운로드 권한과 상관없이 관리자만 받는다.","다만 AI 개발자에게는 감사 이력을 담은 리포트의 [다운로드 요청]도 없다.","감사 이력을 담은 리포트도 모든 구성원의 목록에는 보인다."]},{"제목":"리포트 삭제","문장":["리포트를 삭제하면 확인 뒤 목록과 파일을 지운다.","대기·실행중인 리포트는 삭제할 수 없고, 중지한 뒤 삭제한다.","삭제한 리포트는 되살릴 수 없다.","리포트 삭제는 생성자와 관리자만 할 수 있다."]}]},{"주제":"작업 이력·시스템 로그","개요":"이력 표시 기간과 기록 보존, 작업 이력에 남는 일과 남지 않는 일, 회차 표시, 시스템 로그의 조회와 이어 읽기를 다룬다.","묶음":[{"제목":"이력 표시 기간과 기록 보존","문장":["시스템 설정의 이력 표시 기간은 30일, 90일, 180일, 1년, 3년 가운데 하나이고 처음 값은 180일이다.","이력 표시 기간은 화면에 보이는 기간만 정하고, 기록은 기간이 지나도 지우지 않는다.","작업 이력, 감사 이력, 시스템 로그, 서비스 사용 이력, API Key 발급 내역 모두 같은 규칙을 따른다.","관리자가 기간을 바꿔 [저장]하면 모든 구성원 화면에 바로 적용된다.","기간을 늘리면 그동안 보이지 않던 기록이 바로 다시 보인다.","예를 들어 30일로 두었다가 31일째에 180일로 늘리면 31일 전 기록이 다시 보인다.","기간을 줄여도 지우지 않으므로 확인 창이나 유예가 없다.","리포트와 감사 이력 내보내기는 기간과 상관없이 모든 기록을 쓴다.","회차 롤백과 회차 선택 다운로드도 기간과 상관없이 모든 회차를 쓴다.","표시 기간 밖의 회차는 회차 선택 목록의 「이전 회차 보기」로 연다.","다만 작업이나 파일을 지우면 그 이력은 화면에서 빠지고, 감사 이력의 삭제 기록과 리포트에 쌓인 기록은 남는다."]},{"제목":"작업 이력에 남는 일","문장":["작업 이력에는 사람이 한 시작, 중지, 설정 변경, 결과물, 평가, 테스트, 다운로드가 한 줄씩 남는다.","줄마다 바뀐 칸의 변경 전, 변경 후, 반영 상태, 승인자, 실행 일시, 실행자를 적는다.","실행의 완료와 실패는 별도 줄이 아니라 회차 정보의 상태와 종료 일시로 보인다.","응답 없음과 복구, 연결 대상의 새 회차, 대기 사유 변경처럼 시스템이 바꾼 상태는 「시스템」 줄로 남고 실행자 칸은 「-」다.","오케스트레이터를 거친 일은 줄에 「오케스트레이터」 경유를 표시한다.","권한 없는 구성원의 요청은 변경 줄에 승인 대기로 남고, 승인되면 승인자와 「반영됨」이 채워진다.","요청이 거절되면 반영 상태는 「반려({사유})」다.","다만 화면 이동, 조회, 저장하지 않은 편집, 편집 점유의 시작과 끝은 기록하지 않는다.","파일 미리보기 열람과 권한 트리 조회도 기록하지 않는다."]},{"제목":"회차 표시","문장":["회차는 0회차(생성)부터 매기고, 배포나 학습 실행처럼 작업마다 정한 단위가 시작될 때 새 회차가 열린다.","작업 이력 목록에는 최근 10회차(처음 값)만 보이고, 관리자가 시스템 설정에서 3~50회차 사이로 바꾼다.","표시 회차 수보다 오래된 회차는 리포트에서 본다.","변경 사항은 직전 회차와 비교해 보인다."]},{"제목":"시스템 로그 조회와 이어 읽기","문장":["사용자가 [시스템 로그]를 열면 창을 연 순간까지의 기록을 보인다.","실행 중에 생기는 기록은 상단바 갱신 주기(처음 값 15초)마다 아래에 이어 붙는다.","상단바 갱신 주기가 수동이면 [즉시 수집]을 누를 때만 새 기록이 붙는다.","창은 기간 필터(최근 7일, 30일, 90일, 사용자 지정)로 시작한다.","회차가 있는 작업은 기간 다음에 실행 회차나 배포 회차를 고르고, 선택지는 그 기간에 기록이 있는 회차뿐이다.","기간 안에 회차가 없으면 「기간 안에 실행 회차가 없습니다」를 보인다.","목록을 끝까지 내리면 다음 30건을 이어 읽는다.","다만 기록이 하나도 없으면 [시스템 로그]가 비활성이고 이유를 보인다. 예: 「아직 배포하지 않아 시스템 로그가 없습니다.」","모델 배포와 지식베이스는 생성 기록 줄이 늘 있어 [시스템 로그]가 비활성이 되지 않는다.","시스템 로그 [다운로드]는 다운로드 권한을 거치고, 권한이 없으면 [다운로드 요청]이 승인된 뒤 1회 받는다."]},{"제목":"에러와 경고 구분","문장":["요청 형식 오류, 서버 오류, 실행 실패는 에러로 기록한다.","권한 거부와 호출 한도 초과는 경고로 기록하고, 에러율에 넣지 않고 차단 수로 따로 센다.","호출 한도를 세는 곳에 장애가 나면 그 호출을 막고 시스템 로그에 「한도 확인 불가」로 남긴다."]}]}]')}]);